import { Fragment, useState, useEffect, useCallback } from 'react'
import { toast } from 'sonner'
import {
  Globe, Router, Network, Server, Layers, Box, Container, HardDrive,
  Cpu, Wifi, Camera, Printer, Monitor, MonitorCog, Laptop, Smartphone, PlugZap, Anchor, Package, Circle, Flame,
  Radio, Zap, Lightbulb, RadioTower, Share2,
  type LucideIcon,
} from 'lucide-react'
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { useThemeStore } from '@/stores/themeStore'
import { useCanvasStore } from '@/stores/canvasStore'
import { MIN_HANDLES, clampHandles, sideDefault } from '@/utils/handleUtils'
import { THEMES } from '@/utils/themes'
import { applyOpacity } from '@/utils/colorUtils'
import type {
  NodeType, EdgeType, NodeTypeStyle, EdgeTypeStyle, CustomStyleDef, EdgePathStyle, EdgeLineStyle,
} from '@/types'
import { NODE_TYPE_LABELS, EDGE_TYPE_LABELS } from '@/types'
import {
  EDGE_LINE_STYLES, EDGE_LINE_STYLE_LABELS, EDGE_TYPE_BASE_WIDTH, EDGE_TYPE_DEFAULT_LINE,
  clampWidthMult, dashArrayFor,
} from '@/utils/edgeLineStyle'
import { MarkerShapePicker } from './MarkerShapePicker'
import { normalizeMarker } from '@/utils/edgeMarkers'

// ── Node types exposed for custom style, grouped by category (skip groupRect/group) ──

const NODE_TYPE_GROUPS: { label: string; types: NodeType[] }[] = [
  { label: 'Hardware',       types: ['isp', 'router', 'firewall', 'switch', 'server', 'nas', 'kvm', 'ap', 'printer'] },
  { label: 'Virtualization', types: ['proxmox', 'vm', 'lxc', 'docker_host', 'docker_container'] },
  { label: 'IoT',            types: ['iot', 'camera', 'cpl'] },
  { label: 'Zigbee',         types: ['zigbee_coordinator', 'zigbee_router', 'zigbee_enddevice'] },
  { label: 'Z-Wave',         types: ['zwave_coordinator', 'zwave_router', 'zwave_enddevice'] },
  { label: 'Personal',       types: ['computer', 'laptop', 'mobile'] },
  { label: 'Generic',        types: ['generic'] },
]

const EDITABLE_EDGE_TYPES: EdgeType[] = ['ethernet', 'wifi', 'iot', 'vlan', 'virtual', 'cluster', 'fibre', 'electrical']

const NODE_ICONS: Record<string, LucideIcon> = {
  isp: Globe, router: Router, firewall: Flame, switch: Network, server: Server, proxmox: Layers,
  vm: Box, lxc: Container, nas: HardDrive, kvm: MonitorCog, iot: Cpu, ap: Wifi,
  camera: Camera, printer: Printer, computer: Monitor, laptop: Laptop, mobile: Smartphone, cpl: PlugZap,
  docker_host: Anchor, docker_container: Package,
  zigbee_coordinator: Radio, zigbee_router: Zap, zigbee_enddevice: Lightbulb,
  zwave_coordinator: RadioTower, zwave_router: Share2, zwave_enddevice: Lightbulb,
  generic: Circle,
}

// ── Default style for a node type (from default theme) ─────────────────────

function defaultNodeStyle(nodeType: NodeType): NodeTypeStyle {
  const accent = THEMES.default.colors.nodeAccents[nodeType] ?? THEMES.default.colors.nodeAccents.generic
  return {
    borderColor: accent.border,
    borderOpacity: 1,
    bgColor: THEMES.default.colors.nodeCardBackground,
    bgOpacity: 1,
    iconColor: accent.icon,
    iconOpacity: 1,
    width: 0,
    height: 0,
  }
}

function defaultEdgeStyle(edgeType: EdgeType): EdgeTypeStyle {
  return {
    color: THEMES.default.colors.edgeColors[edgeType],
    opacity: 1,
    pathStyle: 'bezier',
    lineStyle: EDGE_TYPE_DEFAULT_LINE[edgeType],
    widthMult: 1,
    animated: 'none',
    arrowStart: 'none',
    arrowEnd: 'none',
  }
}

// ── Edge line preview (renders the actual dash pattern + width) ────────────────

interface EdgeLineSwatchProps {
  color: string
  lineStyle: EdgeLineStyle
  strokeWidth: number
  width?: number
}

function EdgeLineSwatch({ color, lineStyle, strokeWidth, width = 40 }: EdgeLineSwatchProps) {
  const h = 12
  return (
    <svg width={width} height={h} className="shrink-0" aria-hidden>
      <line
        x1={2}
        y1={h / 2}
        x2={width - 2}
        y2={h / 2}
        stroke={color}
        strokeWidth={strokeWidth}
        strokeDasharray={dashArrayFor(lineStyle, strokeWidth)}
        strokeLinecap={lineStyle === 'dotted' ? 'round' : 'butt'}
      />
    </svg>
  )
}

// ── Color + opacity row ──────────────────────────────────────────────────────

interface ColorRowProps {
  label: string
  color: string
  opacity: number
  onColorChange: (v: string) => void
  onOpacityChange: (v: number) => void
}

function ColorRow({ label, color, opacity, onColorChange, onOpacityChange }: ColorRowProps) {
  return (
    <div className="flex items-center gap-3">
      <span className="text-xs text-[#8b949e] w-20 shrink-0">{label}</span>
      <input
        type="color"
        value={color}
        onChange={(e) => onColorChange(e.target.value)}
        className="w-7 h-7 rounded cursor-pointer border border-[#30363d] bg-transparent p-0.5"
      />
      <div className="flex items-center gap-2 flex-1">
        <input
          type="range"
          min={0}
          max={1}
          step={0.01}
          value={opacity}
          onChange={(e) => onOpacityChange(parseFloat(e.target.value))}
          className="flex-1 h-1 accent-[#00d4ff]"
        />
        <span className="text-xs text-[#8b949e] w-8 text-right">
          {Math.round(opacity * 100)}%
        </span>
      </div>
      <div
        className="w-5 h-5 rounded border border-[#30363d] shrink-0"
        style={{ background: applyOpacity(color, opacity) }}
      />
    </div>
  )
}

// ── Node type editor ─────────────────────────────────────────────────────────

interface NodeEditorProps {
  nodeType: NodeType
  style: NodeTypeStyle
  onChange: (s: NodeTypeStyle) => void
  onApplyToExisting: () => void
}

function NodeEditor({ nodeType, style, onChange, onApplyToExisting }: NodeEditorProps) {
  const set = useCallback(<K extends keyof NodeTypeStyle>(k: K, v: NodeTypeStyle[K]) => {
    onChange({ ...style, [k]: v })
  }, [style, onChange])

  return (
    <div className="flex flex-col gap-4">
      <div className="text-sm font-semibold text-[#e6edf3]">{NODE_TYPE_LABELS[nodeType]}</div>
      <div className="flex flex-col gap-3">
        <ColorRow
          label="Border"
          color={style.borderColor}
          opacity={style.borderOpacity}
          onColorChange={(v) => set('borderColor', v)}
          onOpacityChange={(v) => set('borderOpacity', v)}
        />
        <ColorRow
          label="Background"
          color={style.bgColor}
          opacity={style.bgOpacity}
          onColorChange={(v) => set('bgColor', v)}
          onOpacityChange={(v) => set('bgOpacity', v)}
        />
        <ColorRow
          label="Icon"
          color={style.iconColor}
          opacity={style.iconOpacity}
          onColorChange={(v) => set('iconColor', v)}
          onOpacityChange={(v) => set('iconOpacity', v)}
        />
      </div>

      <div className="border-t border-[#30363d] pt-3">
        <div className="text-xs text-[#8b949e] mb-1">Default size</div>
        <div className="text-xs text-[#8b949e]/60 mb-2">0 = auto (min 140 × 50 px, grows with content)</div>
        <div className="flex gap-3">
          <div className="flex items-center gap-2">
            <span className="text-xs text-[#8b949e]">W</span>
            <input
              type="number"
              min={0}
              step={10}
              value={style.width}
              onChange={(e) => set('width', parseInt(e.target.value, 10) || 0)}
              className="w-20 h-7 text-xs bg-[#0d1117] border border-[#30363d] rounded px-2 text-[#e6edf3]"
            />
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-[#8b949e]">H</span>
            <input
              type="number"
              min={0}
              step={10}
              value={style.height}
              onChange={(e) => set('height', parseInt(e.target.value, 10) || 0)}
              className="w-20 h-7 text-xs bg-[#0d1117] border border-[#30363d] rounded px-2 text-[#e6edf3]"
            />
          </div>
        </div>
      </div>

      <div className="border-t border-[#30363d] pt-3">
        <div className="text-xs text-[#8b949e] mb-1">Default connection points</div>
        <div className="text-xs text-[#8b949e]/60 mb-2">New {NODE_TYPE_LABELS[nodeType]} nodes start with these (0–64 per side)</div>
        <div className="grid grid-cols-2 gap-2">
          {([
            ['Top', 'top', 'topHandles'],
            ['Right', 'right', 'rightHandles'],
            ['Bottom', 'bottom', 'bottomHandles'],
            ['Left', 'left', 'leftHandles'],
          ] as const).map(([label, side, key]) => (
            <div key={side} className="flex items-center gap-2">
              <span className="text-xs text-[#8b949e] w-12">{label}</span>
              <input
                type="number"
                min={MIN_HANDLES}
                max={64}
                step={1}
                value={style[key] ?? sideDefault(side)}
                onChange={(e) => set(key, clampHandles(side, parseInt(e.target.value, 10)))}
                aria-label={`${label} default connection points`}
                className="w-16 h-7 text-xs bg-[#0d1117] border border-[#30363d] rounded px-2 text-[#e6edf3]"
              />
            </div>
          ))}
        </div>
      </div>

      <Button
        size="sm"
        className="self-start bg-[#00d4ff] text-[#0d1117] hover:bg-[#00d4ff]/90"
        onClick={onApplyToExisting}
      >
        Apply to existing {NODE_TYPE_LABELS[nodeType]} nodes
      </Button>
    </div>
  )
}

// ── Edge type editor ─────────────────────────────────────────────────────────

interface EdgeEditorProps {
  edgeType: EdgeType
  style: EdgeTypeStyle
  onChange: (s: EdgeTypeStyle) => void
  onApplyToExisting: () => void
}

function EdgeEditor({ edgeType, style, onChange, onApplyToExisting }: EdgeEditorProps) {
  const set = useCallback(<K extends keyof EdgeTypeStyle>(k: K, v: EdgeTypeStyle[K]) => {
    onChange({ ...style, [k]: v })
  }, [style, onChange])

  return (
    <div className="flex flex-col gap-4">
      <div className="text-sm font-semibold text-[#e6edf3]">{EDGE_TYPE_LABELS[edgeType]}</div>
      <div className="flex flex-col gap-3">
        <ColorRow
          label="Color"
          color={style.color}
          opacity={style.opacity}
          onColorChange={(v) => set('color', v)}
          onOpacityChange={(v) => set('opacity', v)}
        />
      </div>

      <div className="border-t border-[#30363d] pt-3 flex flex-col gap-3">
        <div>
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs text-[#8b949e]">Line style</span>
            <EdgeLineSwatch
              color={applyOpacity(style.color, style.opacity)}
              lineStyle={style.lineStyle}
              strokeWidth={EDGE_TYPE_BASE_WIDTH[edgeType] * style.widthMult}
              width={72}
            />
          </div>
          <div className="flex gap-2">
            {EDGE_LINE_STYLES.map((ls) => (
              <button
                key={ls}
                type="button"
                onClick={() => set('lineStyle', ls)}
                className="px-3 py-1 text-xs rounded border transition-colors"
                style={{
                  borderColor: style.lineStyle === ls ? '#00d4ff' : '#30363d',
                  background: style.lineStyle === ls ? '#00d4ff22' : 'transparent',
                  color: style.lineStyle === ls ? '#00d4ff' : '#8b949e',
                }}
              >
                {EDGE_LINE_STYLE_LABELS[ls]}
              </button>
            ))}
          </div>
        </div>

        <div>
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs text-[#8b949e]">Line width</span>
            <span className="text-xs text-[#8b949e]">{style.widthMult}×</span>
          </div>
          <input
            type="range"
            min={1}
            max={4}
            step={1}
            value={style.widthMult}
            onChange={(e) => set('widthMult', clampWidthMult(parseInt(e.target.value, 10)))}
            aria-label="Line width multiplier"
            className="w-full h-1 accent-[#00d4ff]"
          />
        </div>

        <div>
          <div className="text-xs text-[#8b949e] mb-2">Path style</div>
          <div className="flex gap-2">
            {(['bezier', 'smooth'] as EdgePathStyle[]).map((ps) => (
              <button
                key={ps}
                type="button"
                onClick={() => set('pathStyle', ps)}
                className="px-3 py-1 text-xs rounded border transition-colors"
                style={{
                  borderColor: style.pathStyle === ps ? '#00d4ff' : '#30363d',
                  background: style.pathStyle === ps ? '#00d4ff22' : 'transparent',
                  color: style.pathStyle === ps ? '#00d4ff' : '#8b949e',
                }}
              >
                {ps.charAt(0).toUpperCase() + ps.slice(1)}
              </button>
            ))}
          </div>
        </div>

        <div>
          <div className="text-xs text-[#8b949e] mb-2">Animation</div>
          <select
            value={style.animated}
            onChange={(e) => set('animated', e.target.value as EdgeTypeStyle['animated'])}
            className="w-full h-7 text-xs bg-[#0d1117] border border-[#30363d] rounded px-2 text-[#e6edf3]"
          >
            <option value="none">None</option>
            <option value="basic">Basic</option>
            <option value="flow">Flow</option>
            <option value="snake">Snake</option>
          </select>
        </div>

        <div>
          <div className="text-xs text-[#8b949e] mb-2">Endpoints</div>
          <div className="flex flex-col gap-1.5">
            <MarkerShapePicker label="Start" value={normalizeMarker(style.arrowStart)} onChange={(s) => set('arrowStart', s)} />
            <MarkerShapePicker label="End" value={normalizeMarker(style.arrowEnd)} onChange={(s) => set('arrowEnd', s)} />
          </div>
        </div>
      </div>

      <Button
        size="sm"
        className="self-start bg-[#00d4ff] text-[#0d1117] hover:bg-[#00d4ff]/90"
        onClick={onApplyToExisting}
      >
        Apply to existing {EDGE_TYPE_LABELS[edgeType]} edges
      </Button>
    </div>
  )
}

// ── Main modal ───────────────────────────────────────────────────────────────

type Tab = 'nodes' | 'edges'
type Selection = { kind: 'node'; type: NodeType } | { kind: 'edge'; type: EdgeType } | null

interface CustomStyleModalProps {
  open: boolean
  onClose: () => void
  /** When opening, preselect this node type's editor (shortcut from NodeModal). */
  initialNodeType?: NodeType
}

export function CustomStyleModal({ open, onClose, initialNodeType }: CustomStyleModalProps) {
  const { customStyle, setCustomStyle } = useThemeStore()
  const { markUnsaved, applyTypeNodeStyle, applyTypeEdgeStyle, applyAllCustomStyles } = useCanvasStore()

  const [tab, setTab] = useState<Tab>('nodes')
  const [selection, setSelection] = useState<Selection>(null)
  const [draft, setDraft] = useState<CustomStyleDef>(() => ({
    nodes: { ...customStyle.nodes },
    edges: { ...customStyle.edges },
  }))

  // Reset the draft to the saved customStyle whenever the modal is (re)opened.
  // The parent keeps this component mounted and only toggles `open`, so Radix's
  // onOpenChange never fires for a parent-driven open — we key off the prop edge
  // instead. Without this, abandoned edits (Cancel) would leak into the next open.
  useEffect(() => {
    if (open) {
      setDraft({ nodes: { ...customStyle.nodes }, edges: { ...customStyle.edges } })
      if (initialNodeType) {
        setTab('nodes')
        setSelection({ kind: 'node', type: initialNodeType })
      } else {
        setSelection(null)
      }
    }
    // Intentional snapshot-on-open: we don't want live customStyle changes to
    // clobber an in-progress edit, only a fresh open should reset.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open])

  const handleOpen = (isOpen: boolean) => {
    if (!isOpen) onClose()
  }

  const getNodeStyle = (t: NodeType): NodeTypeStyle =>
    draft.nodes[t] ?? defaultNodeStyle(t)

  const getEdgeStyle = (t: EdgeType): EdgeTypeStyle =>
    draft.edges[t] ?? defaultEdgeStyle(t)

  const handleNodeChange = (t: NodeType, s: NodeTypeStyle) =>
    setDraft((d) => ({ ...d, nodes: { ...d.nodes, [t]: s } }))

  const handleEdgeChange = (t: EdgeType, s: EdgeTypeStyle) =>
    setDraft((d) => ({ ...d, edges: { ...d.edges, [t]: s } }))

  const handleApplyNodeType = (t: NodeType) => {
    const style = getNodeStyle(t)
    applyTypeNodeStyle(t, style)
    toast.success(`Applied style to all ${NODE_TYPE_LABELS[t]} nodes`)
  }

  const handleApplyEdgeType = (t: EdgeType) => {
    const style = getEdgeStyle(t)
    applyTypeEdgeStyle(t, style)
    toast.success(`Applied style to all ${EDGE_TYPE_LABELS[t]} edges`)
  }

  const handleSave = () => {
    setCustomStyle(draft)
    markUnsaved()
    toast.success('Custom style saved — save your canvas to persist')
    onClose()
  }

  const handleApplyAll = () => {
    setCustomStyle(draft)
    applyAllCustomStyles(draft)
    markUnsaved()
    toast.success('Custom style applied to all nodes and edges')
    onClose()
  }

  const selectedNodeStyle = selection?.kind === 'node' ? getNodeStyle(selection.type) : null
  const selectedEdgeStyle = selection?.kind === 'edge' ? getEdgeStyle(selection.type) : null

  return (
    <Dialog open={open} onOpenChange={handleOpen}>
      <DialogContent className="bg-[#161b22] border-[#30363d] max-w-[calc(100%-2rem)] sm:max-w-3xl max-h-[90vh] flex flex-col p-0 gap-0">
        <DialogHeader className="px-5 pt-5 pb-3 border-b border-[#30363d]">
          <DialogTitle className="text-sm font-semibold">Custom Style Editor</DialogTitle>
        </DialogHeader>

        <div className="flex flex-1 overflow-hidden min-h-0">
          {/* Left panel — type list */}
          <div className="w-52 shrink-0 border-r border-[#30363d] flex flex-col overflow-hidden">
            {/* Tabs */}
            <div className="flex border-b border-[#30363d]">
              {(['nodes', 'edges'] as Tab[]).map((t) => (
                <button
                  key={t}
                  type="button"
                  onClick={() => { setTab(t); setSelection(null) }}
                  className="flex-1 py-2 text-xs font-medium transition-colors"
                  style={{
                    borderBottom: tab === t ? '2px solid #00d4ff' : '2px solid transparent',
                    color: tab === t ? '#00d4ff' : '#8b949e',
                  }}
                >
                  {t.charAt(0).toUpperCase() + t.slice(1)}
                </button>
              ))}
            </div>

            {/* Type list */}
            <div className="flex-1 overflow-y-auto py-1">
              {tab === 'nodes' && NODE_TYPE_GROUPS.map((group) => (
                <Fragment key={group.label}>
                  <div className="px-3 pt-2 pb-1 text-[10px] font-semibold uppercase tracking-wider text-[#8b949e]/60">
                    {group.label}
                  </div>
                  {group.types.map((t) => {
                    const Icon = NODE_ICONS[t] ?? Circle
                    const style = draft.nodes[t]
                    const isSelected = selection?.kind === 'node' && selection.type === t
                    const swatchColor = style
                      ? applyOpacity(style.borderColor, style.borderOpacity)
                      : THEMES.default.colors.nodeAccents[t]?.border ?? '#8b949e'

                    return (
                      <button
                        key={t}
                        type="button"
                        onClick={() => setSelection({ kind: 'node', type: t })}
                        className="w-full flex items-center gap-2 px-3 py-2 text-xs transition-colors text-left"
                        style={{
                          background: isSelected ? '#21262d' : 'transparent',
                          color: isSelected ? '#e6edf3' : '#8b949e',
                        }}
                      >
                        <Icon size={13} />
                        <span className="flex-1 truncate">{NODE_TYPE_LABELS[t]}</span>
                        <span
                          className="w-2.5 h-2.5 rounded-full shrink-0"
                          style={{ background: swatchColor }}
                        />
                      </button>
                    )
                  })}
                </Fragment>
              ))}

              {tab === 'edges' && EDITABLE_EDGE_TYPES.map((t) => {
                const style = draft.edges[t]
                const isSelected = selection?.kind === 'edge' && selection.type === t
                const swatchColor = style
                  ? applyOpacity(style.color, style.opacity)
                  : THEMES.default.colors.edgeColors[t]
                const lineStyle = style?.lineStyle ?? EDGE_TYPE_DEFAULT_LINE[t]
                const widthMult = clampWidthMult(style?.widthMult)

                return (
                  <button
                    key={t}
                    type="button"
                    onClick={() => setSelection({ kind: 'edge', type: t })}
                    className="w-full flex items-center gap-2 px-3 py-2 text-xs transition-colors text-left"
                    style={{
                      background: isSelected ? '#21262d' : 'transparent',
                      color: isSelected ? '#e6edf3' : '#8b949e',
                    }}
                  >
                    <span className="flex-1 truncate">{EDGE_TYPE_LABELS[t]}</span>
                    <EdgeLineSwatch
                      color={swatchColor}
                      lineStyle={lineStyle}
                      strokeWidth={EDGE_TYPE_BASE_WIDTH[t] * widthMult}
                    />
                  </button>
                )
              })}
            </div>
          </div>

          {/* Right panel — editor */}
          <div className="flex-1 overflow-y-auto p-5">
            {!selection && (
              <div className="flex items-center justify-center h-full text-xs text-[#8b949e]">
                Select a {tab === 'nodes' ? 'node type' : 'edge type'} from the list to edit its style
              </div>
            )}

            {selection?.kind === 'node' && selectedNodeStyle && (
              <NodeEditor
                key={selection.type}
                nodeType={selection.type}
                style={selectedNodeStyle}
                onChange={(s) => handleNodeChange(selection.type, s)}
                onApplyToExisting={() => handleApplyNodeType(selection.type)}
              />
            )}

            {selection?.kind === 'edge' && selectedEdgeStyle && (
              <EdgeEditor
                key={selection.type}
                edgeType={selection.type}
                style={selectedEdgeStyle}
                onChange={(s) => handleEdgeChange(selection.type, s)}
                onApplyToExisting={() => handleApplyEdgeType(selection.type)}
              />
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="flex justify-between gap-2 px-5 py-3 border-t border-[#30363d]">
          <Button
            type="button"
            size="sm"
            variant="ghost"
            className="text-muted-foreground hover:text-foreground"
            onClick={onClose}
          >
            Cancel
          </Button>
          <div className="flex gap-2">
            <Button
              type="button"
              size="sm"
              variant="outline"
              className="border-[#30363d] text-[#e6edf3] hover:bg-[#21262d]"
              onClick={handleSave}
            >
              Save Custom Style
            </Button>
            <Button
              type="button"
              size="sm"
              className="bg-[#00d4ff] text-[#0d1117] hover:bg-[#00d4ff]/90"
              onClick={handleApplyAll}
            >
              Apply All to Canvas
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

import { useState, useEffect, useCallback, useRef, useMemo } from 'react'
import {
  Server, Layers,
  Search, RefreshCw, X, CheckCircle2, EyeOff, Trash2, Loader2, ServerCog,
} from 'lucide-react'
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { scanApi, type DuplicateNodeConflict } from '@/api/ha'
import { useCanvasStore } from '@/stores/canvasStore'
import { useDesignStore } from '@/stores/designStore'
import { useThemeStore } from '@/stores/themeStore'
import { resolveNodeColors } from '@/utils/nodeColors'
import { NODE_TYPE_DEFAULT_ICONS } from '@/utils/nodeIcons'
import { toast } from 'sonner'
import { PendingDeviceModal, type PendingDevice } from '@/components/modals/PendingDeviceModal'
import type { NodeType, ServiceInfo } from '@/types'
import { buildZigbeeProperties, isZigbeeType } from '@/utils/zigbeeProperties'
import { buildZwaveProperties, isZwaveType } from '@/utils/zwaveProperties'
import { sourceBuckets, orderedSources, isRackDevice, SOURCE_META, type SourceBucket } from '@/utils/pendingSources'
import { isRackable } from '@/utils/rackable'
import { buildMacProperty } from '@/utils/macProperty'
import { formatRelative, formatTimestamp } from '@/utils/timeFormat'
import { getCenteredPosition } from '@/utils/viewportCenter'
import { applyAutoEdges, type AutoEdge } from '@/utils/autoEdges'

const STANDALONE = import.meta.env.VITE_STANDALONE === 'true'

interface PendingDevicesModalProps {
  open: boolean
  onClose: () => void
  highlightId?: string
  initialStatus?: 'pending' | 'hidden'
  /**
   * Picker mode. Clicking a card hands the device back instead of opening its
   * detail modal, so another feature (the rack canvas) can reuse this list —
   * search, filters, badges and all — rather than reimplementing a `<select>`.
   */
  onPick?: (device: PendingDevice) => void
  /** Start with the Rackable filter on (what the rack picker wants). */
  initialRackableOnly?: boolean
}

const PORT_COLORS: Record<number, string> = {
  22: '#a855f7',
  80: '#00d4ff',
  443: '#39d353',
  53: '#e3b341',
  3306: '#a855f7',
  5432: '#a855f7',
  6379: '#f85149',
  9090: '#e3b341',
  3000: '#00d4ff',
  8080: '#00d4ff',
  8443: '#39d353',
}

const CATEGORY_COLORS: Record<string, string> = {
  hypervisor: '#ff6e00',
  nas: '#39d353',
  automation: '#a855f7',
  containers: '#00d4ff',
  network: '#39d353',
  security: '#f85149',
  monitoring: '#e3b341',
  database: '#a855f7',
  web: '#00d4ff',
  media: '#ff6e00',
  iot: '#e3b341',
}

function serviceColor(port: number | null | undefined, category?: string | null): string {
  if (port != null && PORT_COLORS[port]) return PORT_COLORS[port]
  if (category && CATEGORY_COLORS[category.toLowerCase()]) return CATEGORY_COLORS[category.toLowerCase()]
  return '#8b949e'
}

type SourceFilter = 'all' | SourceBucket
type StatusFilter = 'pending' | 'hidden'

const COMMON_PORTS = new Set([22, 80, 443])

/**
 * What the device is. The curated `type` wins over the discovery guess: a
 * device drawn on a canvas only ever has the former, and an edit that retypes a
 * scanned row must not keep reading the scanner's opinion.
 */
function deviceType(d: PendingDevice): NodeType | null {
  return ((d.type ?? d.suggested_type) as NodeType) ?? null
}

function specialServiceName(d: PendingDevice): string | undefined {
  const candidates = (d.services ?? []).filter(
    (s) => s.category != null && s.port != null && !COMMON_PORTS.has(s.port) && s.service_name,
  )
  const nonWeb = candidates.find((s) => s.category?.toLowerCase() !== 'web')
  return (nonWeb ?? candidates[0])?.service_name ?? undefined
}

function deviceLabel(d: PendingDevice): string {
  // Same precedence as the detail modal — the name the user gave it first.
  return d.label ?? d.friendly_name ?? d.hostname ?? specialServiceName(d) ?? d.ip ?? d.ieee_address ?? 'device'
}

/** Server auto-edge as returned by approve/bulkApprove (camelCase handles). */
interface ServerAutoEdge {
  id: string
  source: string
  target: string
  type?: string
  sourceHandle?: string | null
  targetHandle?: string | null
  source_handle?: string | null
  target_handle?: string | null
}

function injectAutoEdges(edges: ServerAutoEdge[] | undefined) {
  if (!edges || edges.length === 0) return
  // Honor the server's edge type + handle IDs (iot bottom→top-t for mesh links,
  // cluster right→left for Proxmox hosts) and bump the referenced nodes' side
  // handle counts so left/right connection points actually exist — otherwise
  // React Flow can't resolve the handle and falls back to the top handle.
  const autoEdges: AutoEdge[] = edges.map((e) => ({
    id: e.id,
    source: e.source,
    target: e.target,
    type: e.type,
    source_handle: e.source_handle ?? e.sourceHandle,
    target_handle: e.target_handle ?? e.targetHandle,
  }))
  useCanvasStore.setState((state) => {
    const next = applyAutoEdges(state.nodes, state.edges, autoEdges)
    return { nodes: next.nodes, edges: next.edges, hasUnsavedChanges: true }
  })
}

export function PendingDevicesModal({ open, onClose, highlightId, initialStatus = 'pending', onPick, initialRackableOnly = false }: PendingDevicesModalProps) {
  const [devices, setDevices] = useState<PendingDevice[]>([])
  const [loading, setLoading] = useState(false)
  const [selected, setSelected] = useState<PendingDevice | null>(null)
  const [selectMode, setSelectMode] = useState(false)
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set())
  const [search, setSearch] = useState('')
  const [sourceFilter, setSourceFilter] = useState<SourceFilter>('all')
  const [typeFilter, setTypeFilter] = useState<string>('all')
  const [statusFilter, setStatusFilter] = useState<StatusFilter>(initialStatus)
  // Inventory shows on-canvas devices by default; toggle off to hide them.
  const [showOnCanvas, setShowOnCanvas] = useState(true)
  // Optionally restrict to devices that have at least one detected service.
  const [withServicesOnly, setWithServicesOnly] = useState(false)
  // Hardware only — what a rack can hold. On by default when the rack canvas
  // opens the inventory to pick a mount.
  const [rackableOnly, setRackableOnly] = useState(initialRackableOnly)
  const { addNode, scanEventTs } = useCanvasStore()
  const setSelectedNode = useCanvasStore((s) => s.setSelectedNode)
  const activeDesignId = useDesignStore((s) => s.activeDesignId)
  const highlightRef = useRef<HTMLButtonElement>(null)
  // Set when a single approve is refused because the same host is already on
  // this design — the user decides: link to the existing node or duplicate.
  const [dupPrompt, setDupPrompt] = useState<{ device: PendingDevice; conflict: DuplicateNodeConflict } | null>(null)

  const load = useCallback(async () => {
    setLoading(true)
    try {
      const res = statusFilter === 'pending' ? await scanApi.pending() : await scanApi.hidden()
      setDevices(res.data as PendingDevice[])
    } catch {
      toast.error(`Failed to load ${statusFilter} devices`)
    } finally {
      setLoading(false)
    }
  }, [statusFilter])

  useEffect(() => { if (open) load() }, [open, load])
  useEffect(() => { if (open && scanEventTs > 0) load() }, [scanEventTs, open, load])

  useEffect(() => {
    if (!open) {
      setSelectMode(false)
      setSelectedIds(new Set())
      setSearch('')
    } else {
      setStatusFilter(initialStatus)
      // Reopening from the rack picker must re-arm the filter even if the user
      // turned it off during the previous visit.
      setRackableOnly(initialRackableOnly)
    }
  }, [open, initialStatus, initialRackableOnly])

  const distinctTypes = useMemo(() => {
    const set = new Set<string>()
    devices.forEach((d) => { const t = deviceType(d); if (t) set.add(t) })
    return [...set].sort()
  }, [devices])

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase()
    return devices.filter((d) => {
      // A device merged across sources (e.g. IP scan + Proxmox) matches every
      // filter for a source that has seen it.
      if (sourceFilter !== 'all' && !sourceBuckets(d).has(sourceFilter)) return false
      if (typeFilter !== 'all' && deviceType(d) !== typeFilter) return false
      // Inventory-only: optionally hide devices already placed on a canvas.
      if (statusFilter === 'pending' && !showOnCanvas && (d.canvas_count ?? 0) > 0) return false
      if (withServicesOnly && (d.services?.length ?? 0) === 0) return false
      if (rackableOnly && !isRackable(d)) return false
      if (q) {
        const hay = [
          d.friendly_name, d.hostname, d.ip, d.mac, d.ieee_address, d.vendor, d.model,
          ...d.services.map((s) => s.service_name),
        ].filter(Boolean).join(' ').toLowerCase()
        if (!hay.includes(q)) return false
      }
      return true
    })
  }, [devices, search, sourceFilter, typeFilter, statusFilter, showOnCanvas, withServicesOnly, rackableOnly])

  useEffect(() => {
    if (!highlightId || loading || !open) return
    highlightRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
  }, [highlightId, loading, open, filtered])

  const toggleSelect = (id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id); else next.add(id)
      return next
    })
  }

  const handleCardClick = (d: PendingDevice) => {
    // Picker mode wins over everything else: the caller opened this list to get
    // one device back, not to approve or hide anything.
    if (onPick) { onPick(d); return }
    if (selectMode) { toggleSelect(d.id); return }
    if (statusFilter === 'hidden') { handleRestore(d); return }
    setSelected(d)
  }

  const handleRestore = async (device: PendingDevice) => {
    try {
      await scanApi.restore(device.id)
      setDevices((prev) => prev.filter((d) => d.id !== device.id))
      toast.success(`Restored ${deviceLabel(device)}`)
    } catch {
      toast.error('Failed to restore device')
    }
  }

  const handleBulkRestore = async () => {
    const ids = [...selectedIds]
    if (ids.length === 0) return
    try {
      const res = await scanApi.bulkRestore(ids)
      setDevices((prev) => prev.filter((d) => !ids.includes(d.id)))
      setSelectedIds(new Set())
      toast.success(`Restored ${res.data.restored} device${res.data.restored !== 1 ? 's' : ''}`)
    } catch {
      toast.error('Failed to bulk restore devices')
    }
  }

  const enterSelectMode = () => setSelectMode(true)
  const exitSelectMode = () => { setSelectMode(false); setSelectedIds(new Set()) }
  const selectAllVisible = () => setSelectedIds(new Set(filtered.map((d) => d.id)))

  const handleClearAll = async () => {
    const targets = filtered
    if (targets.length === 0) return
    const filtersActive = targets.length !== devices.length
    try {
      if (filtersActive) {
        const results = await Promise.allSettled(targets.map((d) => scanApi.ignore(d.id)))
        const failed = results.filter((r) => r.status === 'rejected').length
        const removedIds = new Set(
          targets.filter((_, i) => results[i].status === 'fulfilled').map((d) => d.id)
        )
        setDevices((prev) => prev.filter((d) => !removedIds.has(d.id)))
        setSelectedIds(new Set())
        if (failed > 0) toast.error(`Removed ${removedIds.size}, ${failed} failed`)
        else toast.success(`Removed ${removedIds.size} device${removedIds.size !== 1 ? 's' : ''}`)
      } else {
        // Clears only pending rows server-side; approved/on-canvas devices stay,
        // so reload rather than blanking the whole inventory.
        await scanApi.clearPending()
        setSelectedIds(new Set())
        await load()
        toast.success('Pending devices cleared')
      }
    } catch {
      toast.error('Failed to clear pending devices')
    }
  }

  // force=true is sent only after the user confirms they want a duplicate node
  // on this design (the backend otherwise returns a `duplicate` conflict so we
  // can ask instead of silently doubling the card).
  const approveDevice = async (device: PendingDevice, force = false) => {
    // Rack gear documents a mount, not a host: it stays out of logical canvases.
    // The backend refuses it too — this is the friendly half of the guard.
    if (isRackDevice(device)) {
      toast.error('Rack devices belong to a rack canvas, not a logical one')
      return
    }
    const fallbackLabel = deviceLabel(device)
    const type = deviceType(device) ?? 'generic'
    const zwave = isZwaveType(type)
    const wireless = isZigbeeType(type) || zwave
    const nodeData = {
      label: fallbackLabel,
      type,
      ip: device.ip ?? undefined,
      mac: device.mac ?? undefined,
      hostname: device.hostname ?? undefined,
      status: wireless ? 'online' : 'unknown',
      services: (device.services ?? []) as ServiceInfo[],
      // Non-wireless devices keep the hidden rows the backend already put on
      // the pending device (e.g. Proxmox VMID/CPU/RAM/Disk/Kind/Source) and add
      // MAC — rebuilding from scratch would drop the Proxmox specs.
      properties: zwave
        ? buildZwaveProperties(device)
        : isZigbeeType(type)
          ? buildZigbeeProperties(device)
          : [...(device.properties ?? []), ...buildMacProperty(device.mac)],
    }
    try {
      const res = await scanApi.approve(device.id, { ...nodeData, force }, activeDesignId)
      // Same host already on this design: ask before creating a second card
      // (only on the first, non-forced attempt).
      if (res.data.duplicate && !force) {
        // Close the device-detail modal first so the prompt isn't trapped
        // behind another open dialog.
        setSelected(null)
        setDupPrompt({ device, conflict: res.data.duplicate })
        return
      }
      const nodeId = res.data.node_id
      if (!nodeId) { toast.error('Failed to approve device'); return }
      addNode({
        id: nodeId,
        type: nodeData.type,
        position: getCenteredPosition(),
        data: {
          ...nodeData,
          status: wireless ? ('online' as const) : ('unknown' as const),
          // The row this node draws — lets an inventory edit reach it on screen.
          device_id: res.data.node?.device_id ?? device.id,
        },
      })
      injectAutoEdges(res.data.edges)
      const created = res.data.edges_created ?? 0
      const extra = created > 0 ? ` (+${created} link${created !== 1 ? 's' : ''})` : ''
      toast.success(`Approved ${nodeData.label}${extra}`)
      // Keep the row (now on-canvas, shown with an "In N canvas" badge); reload
      // for a fresh canvas_count rather than dropping it until reopen.
      setSelected(null)
      setDupPrompt(null)
      await load()
    } catch {
      toast.error('Failed to approve device')
    }
  }

  const handleApprove = (device: PendingDevice) => approveDevice(device, false)

  const goToExistingNode = (nodeId: string) => {
    setSelectedNode(nodeId)
    setDupPrompt(null)
    setSelected(null)
    onClose()
  }

  const handleHide = async (device: PendingDevice) => {
    try {
      await scanApi.hide(device.id)
      setDevices((prev) => prev.filter((d) => d.id !== device.id))
      setSelected(null)
      toast.success('Device hidden')
    } catch {
      toast.error('Failed to hide device')
    }
  }

  const handleIgnore = async (device: PendingDevice) => {
    try {
      await scanApi.ignore(device.id)
      setDevices((prev) => prev.filter((d) => d.id !== device.id))
      setSelected(null)
    } catch (err) {
      // The row holds the facts of the nodes drawing it, so the integration
      // refuses to drop it while one does.
      if ((err as { code?: string } | null)?.code === 'in_use') {
        toast.error('This device is on a canvas — delete its node or hide it instead')
      } else {
        toast.error('Failed to remove device')
      }
    }
  }

  const handleBulkApprove = async () => {
    const rackIds = new Set(devices.filter(isRackDevice).map((d) => d.id))
    const ids = [...selectedIds].filter((id) => !rackIds.has(id))
    const skippedRack = selectedIds.size - ids.length
    if (skippedRack > 0) {
      toast.error(
        `${skippedRack} rack device${skippedRack > 1 ? 's' : ''} skipped — they belong to a rack canvas`,
      )
    }
    if (ids.length === 0) return
    try {
      const res = await scanApi.bulkApprove(ids, {}, activeDesignId)
      const deviceToNode: Record<string, string> = {}
      res.data.device_ids.forEach((did, i) => { deviceToNode[did] = res.data.node_ids[i] })
      const approvedDevices = devices.filter((d) => ids.includes(d.id))
      const cols = Math.min(4, approvedDevices.length)
      const rows = Math.ceil(approvedDevices.length / 4)
      const origin = getCenteredPosition(cols * 160, rows * 100)
      approvedDevices.forEach((d, i) => {
        const nodeId = deviceToNode[d.id]
        if (!nodeId) return
        const type = deviceType(d) ?? 'generic'
        const zwave = isZwaveType(type)
        const wireless = isZigbeeType(type) || zwave
        addNode({
          id: nodeId,
          type,
          position: { x: origin.x + (i % 4) * 160, y: origin.y + Math.floor(i / 4) * 100 },
          data: {
            label: deviceLabel(d),
            type,
            device_id: d.id,
            ip: d.ip ?? undefined,
            mac: d.mac ?? undefined,
            hostname: d.hostname ?? undefined,
            status: wireless ? ('online' as const) : ('unknown' as const),
            services: (d.services ?? []) as ServiceInfo[],
            // Keep the backend's hidden rows (Proxmox specs) and add MAC.
            properties: zwave
              ? buildZwaveProperties(d)
              : isZigbeeType(type)
                ? buildZigbeeProperties(d)
                : [...(d.properties ?? []), ...buildMacProperty(d.mac)],
          },
        })
      })
      injectAutoEdges(res.data.edges)
      // Don't strip approved rows locally: the inventory keeps them with an
      // "In N canvas" badge (that's what showOnCanvas toggles). Reload so they
      // reappear with a fresh canvas_count instead of vanishing until reopen.
      setSelectedIds(new Set())
      await load()
      const linkExtra = res.data.edges_created > 0 ? ` (+${res.data.edges_created} link${res.data.edges_created !== 1 ? 's' : ''})` : ''
      toast.success(`Approved ${res.data.approved} device${res.data.approved !== 1 ? 's' : ''}${linkExtra}`)
      // Bulk can't prompt per-device, so report the ones already on this canvas
      // (skipped as duplicates) instead of silently dropping them.
      const dupes = res.data.skipped_devices ?? []
      if (dupes.length > 0) {
        const names = dupes.slice(0, 3).map((d) => d.label).join(', ')
        const more = dupes.length > 3 ? ` +${dupes.length - 3} more` : ''
        toast.info(
          `${dupes.length} already on this canvas, skipped: ${names}${more}`,
          { description: 'Matched an existing node by IP/MAC/IEEE on this design.' },
        )
      }
    } catch {
      toast.error('Failed to bulk approve devices')
    }
  }

  const handleBulkHide = async () => {
    const ids = [...selectedIds]
    if (ids.length === 0) return
    try {
      const res = await scanApi.bulkHide(ids)
      setDevices((prev) => prev.filter((d) => !ids.includes(d.id)))
      setSelectedIds(new Set())
      toast.success(`Hidden ${res.data.hidden} device${res.data.hidden !== 1 ? 's' : ''}`)
    } catch {
      toast.error('Failed to bulk hide devices')
    }
  }

  const searchRef = useRef<HTMLInputElement>(null)
  useEffect(() => {
    if (!open) return
    const handler = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null
      const inField = target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.tagName === 'SELECT')
      if (e.key === 'Escape') {
        if (selectMode && selectedIds.size > 0) { e.preventDefault(); setSelectedIds(new Set()) }
        return
      }
      if (inField) return
      if (e.key === '/') { e.preventDefault(); searchRef.current?.focus() }
      // Bulk actions are meaningless in picker mode — the card click returns a
      // device, so select mode must stay unreachable from the keyboard too.
      else if (onPick) return
      else if (e.key.toLowerCase() === 's') { e.preventDefault(); if (selectMode) exitSelectMode(); else enterSelectMode() }
      else if (e.key.toLowerCase() === 'a' && selectMode) { e.preventDefault(); selectAllVisible() }
      else if (e.key === 'Enter' && selectMode && selectedIds.size > 0) { e.preventDefault(); handleBulkApprove() }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, selectMode, selectedIds, filtered, onPick])

  return (
    <>
      <Dialog open={open} onOpenChange={(v) => { if (!v) onClose() }}>
        <DialogContent
          showCloseButton={false}
          className="!max-w-none w-[95vw] h-[90vh] p-0 flex flex-col gap-0 bg-[#0d1117] border-border"
        >
          <DialogHeader className="px-4 py-3 border-b border-border shrink-0">
            <div className="flex items-center justify-between gap-3">
              <DialogTitle className="text-base font-semibold flex items-center gap-2">
                {onPick ? 'Pick a Device' : statusFilter === 'pending' ? 'Device Inventory' : 'Hidden Devices'}
                <span className="text-muted-foreground font-normal text-xs">
                  ({filtered.length}{filtered.length !== devices.length && ` of ${devices.length}`})
                </span>
              </DialogTitle>
              <div className="flex items-center gap-1">
                <button onClick={load} className="text-muted-foreground hover:text-foreground p-1.5 rounded transition-colors" title="Refresh">
                  <RefreshCw size={14} />
                </button>
                {/* Never offer a destructive bulk clear from a picker. */}
                {!onPick && statusFilter === 'pending' && devices.length > 0 && (
                  <button
                    onClick={handleClearAll}
                    className="text-muted-foreground hover:text-[#f85149] p-1.5 rounded transition-colors"
                    title={filtered.length !== devices.length ? `Remove ${filtered.length} filtered` : 'Clear all pending'}
                  >
                    <Trash2 size={14} />
                  </button>
                )}
                <button onClick={onClose} className="text-muted-foreground hover:text-foreground p-1.5 rounded transition-colors" title="Close">
                  <X size={14} />
                </button>
              </div>
            </div>
          </DialogHeader>

          <div className="px-4 py-2 border-b border-border bg-[#161b22] shrink-0 flex flex-wrap items-center gap-2">
            <div className="relative flex-1 min-w-[200px] max-w-md">
              <Search size={12} className="absolute left-2 top-1/2 -translate-y-1/2 text-muted-foreground" />
              <input
                ref={searchRef}
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search name, IP, MAC, IEEE, service…"
                className="w-full text-xs bg-[#0d1117] border border-border rounded px-7 py-1.5 outline-none focus:border-[#00d4ff]/50"
              />
            </div>
            <div className="flex rounded border border-border overflow-hidden text-xs" role="group" aria-label="Source filter">
              <button
                onClick={() => setSourceFilter('all')}
                className={`px-2.5 py-1.5 transition-colors ${sourceFilter === 'all' ? 'bg-[#00d4ff]/20 text-[#00d4ff]' : 'bg-[#0d1117] text-muted-foreground hover:text-foreground'}`}
              >
                All
              </button>
              <button
                onClick={() => setSourceFilter('ip')}
                className={`px-2.5 py-1.5 transition-colors border-l border-border ${sourceFilter === 'ip' ? 'bg-[#a855f7]/20 text-[#a855f7]' : 'bg-[#0d1117] text-muted-foreground hover:text-foreground'}`}
              >
                IP scan
              </button>
              <button
                onClick={() => setSourceFilter('zigbee')}
                className={`px-2.5 py-1.5 transition-colors border-l border-border ${sourceFilter === 'zigbee' ? 'bg-[#00d4ff]/20 text-[#00d4ff]' : 'bg-[#0d1117] text-muted-foreground hover:text-foreground'}`}
              >
                Zigbee
              </button>
              <button
                onClick={() => setSourceFilter('zwave')}
                className={`px-2.5 py-1.5 transition-colors border-l border-border ${sourceFilter === 'zwave' ? 'bg-[#ff6e00]/20 text-[#ff6e00]' : 'bg-[#0d1117] text-muted-foreground hover:text-foreground'}`}
              >
                Z-Wave
              </button>
              {!STANDALONE && (
                <button
                  onClick={() => setSourceFilter('proxmox')}
                  className={`px-2.5 py-1.5 transition-colors border-l border-border ${sourceFilter === 'proxmox' ? 'bg-[#e57000]/20 text-[#e57000]' : 'bg-[#0d1117] text-muted-foreground hover:text-foreground'}`}
                >
                  Proxmox
                </button>
              )}
              <button
                onClick={() => setSourceFilter('rack')}
                className={`px-2.5 py-1.5 transition-colors border-l border-border ${sourceFilter === 'rack' ? 'bg-[#39d353]/20 text-[#39d353]' : 'bg-[#0d1117] text-muted-foreground hover:text-foreground'}`}
                title="Gear created from a rack canvas"
              >
                Rack devices
              </button>
              <button
                onClick={() => setSourceFilter('canvas')}
                className={`px-2.5 py-1.5 transition-colors border-l border-border ${sourceFilter === 'canvas' ? 'bg-[#8b949e]/20 text-foreground' : 'bg-[#0d1117] text-muted-foreground hover:text-foreground'}`}
                title="Documented directly on a canvas — no scan ever saw it"
              >
                Canvas
              </button>
            </div>
            <select
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
              className="text-xs bg-[#0d1117] border border-border rounded px-2 py-1.5 outline-none focus:border-[#00d4ff]/50"
              aria-label="Type filter"
            >
              <option value="all">All types</option>
              {distinctTypes.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
            <div className="flex rounded border border-border overflow-hidden text-xs">
              <button
                onClick={() => setStatusFilter('pending')}
                className={`px-2.5 py-1.5 transition-colors ${statusFilter === 'pending' ? 'bg-[#00d4ff]/20 text-[#00d4ff]' : 'bg-[#0d1117] text-muted-foreground hover:text-foreground'}`}
              >
                Inventory
              </button>
              <button
                onClick={() => setStatusFilter('hidden')}
                className={`px-2.5 py-1.5 transition-colors ${statusFilter === 'hidden' ? 'bg-[#8b949e]/20 text-foreground' : 'bg-[#0d1117] text-muted-foreground hover:text-foreground'}`}
              >
                Hidden
              </button>
            </div>
            {statusFilter === 'pending' && (
              <button
                onClick={() => setShowOnCanvas((v) => !v)}
                className={`flex items-center gap-1.5 text-xs px-2.5 py-1.5 rounded border transition-colors ${showOnCanvas ? 'bg-[#0d1117] text-muted-foreground border-border hover:text-foreground' : 'bg-[#00d4ff]/20 text-[#00d4ff] border-[#00d4ff]/50'}`}
                title="Show or hide devices already on a canvas"
                aria-pressed={!showOnCanvas}
              >
                <Layers size={12} />
                {showOnCanvas ? 'Hide on-canvas' : 'Show on-canvas'}
              </button>
            )}
            <button
              onClick={() => setWithServicesOnly((v) => !v)}
              className={`flex items-center gap-1.5 text-xs px-2.5 py-1.5 rounded border transition-colors ${withServicesOnly ? 'bg-[#00d4ff]/20 text-[#00d4ff] border-[#00d4ff]/50' : 'bg-[#0d1117] text-muted-foreground border-border hover:text-foreground'}`}
              title="Only show devices with at least one detected service"
              aria-pressed={withServicesOnly}
            >
              <ServerCog size={12} />
              With services
            </button>
            <button
              onClick={() => setRackableOnly((v) => !v)}
              className={`flex items-center gap-1.5 text-xs px-2.5 py-1.5 rounded border transition-colors ${rackableOnly ? 'bg-[#39d353]/20 text-[#39d353] border-[#39d353]/50' : 'bg-[#0d1117] text-muted-foreground border-border hover:text-foreground'}`}
              title="Only show hardware you could mount in a rack (no VMs, containers or mesh devices)"
              aria-pressed={rackableOnly}
            >
              <Server size={12} />
              Rackable
            </button>
            {!onPick && (
              <button
                onClick={() => selectMode ? exitSelectMode() : enterSelectMode()}
                className={`text-xs px-2.5 py-1.5 rounded border transition-colors ${selectMode ? 'bg-[#00d4ff]/20 text-[#00d4ff] border-[#00d4ff]/50' : 'bg-[#0d1117] text-muted-foreground border-border hover:text-foreground'}`}
                title="Toggle select mode (s)"
              >
                {selectMode ? 'Exit select' : 'Select mode'}
              </button>
            )}
          </div>

          <div className="flex-1 min-h-0 overflow-y-auto p-4">
            {loading && (
              <div className="flex items-center justify-center py-10">
                <Loader2 size={20} className="animate-spin text-muted-foreground" />
              </div>
            )}
            {!loading && filtered.length === 0 && (
              <p className="text-xs text-muted-foreground text-center py-10">
                {devices.length === 0 ? `No ${statusFilter} devices` : 'No devices match filters'}
              </p>
            )}
            {!loading && filtered.length > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-2">
                {filtered.map((d) => (
                  <DeviceCard
                    key={d.id}
                    device={d}
                    selected={selectedIds.has(d.id)}
                    selectMode={selectMode}
                    highlighted={d.id === highlightId}
                    onClick={() => handleCardClick(d)}
                    cardRef={d.id === highlightId ? highlightRef : undefined}
                  />
                ))}
              </div>
            )}
          </div>

          {selectMode && (
            <div className="px-4 py-2.5 border-t border-border bg-[#161b22] shrink-0 flex items-center gap-2 flex-wrap">
              <span className="text-xs text-muted-foreground mr-1">
                {selectedIds.size} selected
              </span>
              <button
                onClick={selectAllVisible}
                className="text-xs px-2.5 py-1.5 rounded border border-border text-muted-foreground hover:text-foreground transition-colors"
              >
                Select all visible ({filtered.length})
              </button>
              <button
                onClick={() => setSelectedIds(new Set())}
                disabled={selectedIds.size === 0}
                className="text-xs px-2.5 py-1.5 rounded border border-border text-muted-foreground hover:text-foreground disabled:opacity-40 transition-colors"
              >
                Clear
              </button>
              <div className="flex-1" />
              {statusFilter === 'pending' && (
                <>
                  <button
                    onClick={handleBulkApprove}
                    disabled={selectedIds.size === 0}
                    className="text-xs px-3 py-1.5 rounded bg-[#39d353]/20 text-[#39d353] hover:bg-[#39d353]/30 disabled:opacity-40 font-medium transition-colors"
                  >
                    Approve ({selectedIds.size})
                  </button>
                  <button
                    onClick={handleBulkHide}
                    disabled={selectedIds.size === 0}
                    className="text-xs px-3 py-1.5 rounded bg-[#8b949e]/20 text-[#8b949e] hover:bg-[#8b949e]/30 disabled:opacity-40 font-medium transition-colors"
                  >
                    Hide ({selectedIds.size})
                  </button>
                </>
              )}
              {statusFilter === 'hidden' && (
                <button
                  onClick={handleBulkRestore}
                  disabled={selectedIds.size === 0}
                  className="text-xs px-3 py-1.5 rounded bg-[#e3b341]/20 text-[#e3b341] hover:bg-[#e3b341]/30 disabled:opacity-40 font-medium transition-colors"
                >
                  Restore ({selectedIds.size})
                </button>
              )}
            </div>
          )}

          {/* Duplicate confirmation: the host is already on this design. Ask
              before creating a second card — never silently drop or duplicate.
              Rendered INSIDE the inventory DialogContent on purpose: an open
              dialog marks outside content inert/aria-hidden, so a sibling
              overlay would be unclickable. Keeping it in the dialog's own
              subtree avoids that. */}
          {dupPrompt && (
            <div
              role="dialog"
              aria-modal="true"
              aria-label="Device already on this canvas"
              className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4"
              onClick={() => setDupPrompt(null)}
            >
              <div
                className="w-full max-w-md rounded-lg border border-border bg-[#161b22] p-5 shadow-xl"
                onClick={(e) => e.stopPropagation()}
              >
                <h2 className="text-base font-semibold text-foreground mb-3">Device already on this canvas</h2>
                <div className="text-sm text-muted-foreground space-y-3">
                  <p>
                    <span className="text-foreground font-medium break-all">{deviceLabel(dupPrompt.device)}</span>{' '}
                    matches a node already on this design
                    {' '}(<span className="uppercase text-[11px] font-mono">{dupPrompt.conflict.match}</span>{' '}
                    <span className="font-mono text-foreground">{dupPrompt.conflict.value}</span>)
                    {dupPrompt.conflict.existing_label ? (
                      <>: <span className="text-foreground font-medium break-all">{dupPrompt.conflict.existing_label}</span></>
                    ) : null}.
                  </p>
                  <p>Add it again anyway, or jump to the existing node?</p>
                  <div className="flex flex-wrap justify-end gap-2 pt-1">
                    <button
                      onClick={() => setDupPrompt(null)}
                      className="text-xs px-3 py-1.5 rounded border border-border text-muted-foreground hover:text-foreground transition-colors"
                    >
                      Cancel
                    </button>
                    <button
                      onClick={() => goToExistingNode(dupPrompt.conflict.existing_node_id)}
                      className="text-xs px-3 py-1.5 rounded bg-[#00d4ff]/20 text-[#00d4ff] hover:bg-[#00d4ff]/30 font-medium transition-colors"
                    >
                      Go to existing node
                    </button>
                    <button
                      onClick={() => approveDevice(dupPrompt.device, true)}
                      className="text-xs px-3 py-1.5 rounded bg-[#e3b341]/20 text-[#e3b341] hover:bg-[#e3b341]/30 font-medium transition-colors"
                    >
                      Add duplicate anyway
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

      <PendingDeviceModal
        // A fresh form per device: the grid stays mounted across card clicks.
        key={selected?.id ?? 'none'}
        device={selected}
        onClose={() => setSelected(null)}
        onApprove={handleApprove}
        onHide={handleHide}
        onIgnore={handleIgnore}
        onSaved={(saved) => {
          // Patch in place rather than refetch: the grid keeps its scroll
          // position and the open detail modal keeps showing the same device.
          setDevices((prev) => prev.map((d) => (d.id === saved.id ? saved : d)))
          setSelected(saved)
        }}
      />
    </>
  )
}

interface DeviceCardProps {
  device: PendingDevice
  selected: boolean
  selectMode: boolean
  highlighted: boolean
  onClick: () => void
  cardRef?: React.Ref<HTMLButtonElement>
}

function DeviceCard({ device, selected, selectMode, highlighted, onClick, cardRef }: DeviceCardProps) {
  const roleType = deviceType(device) ?? 'generic'
  const Icon = NODE_TYPE_DEFAULT_ICONS[roleType] ?? NODE_TYPE_DEFAULT_ICONS.generic
  const activeTheme = useThemeStore((s) => s.activeTheme)
  // Colour the role badge with the same accent the node uses on the canvas
  // (from the active theme / style section), instead of a flat grey.
  const roleColor = resolveNodeColors({ type: roleType, custom_colors: undefined }, activeTheme).border
  const label = deviceLabel(device)
  // A device may carry more than one source (e.g. IP scan + Proxmox); render one
  // badge per source so the merge is visible.
  const sourceBadges = orderedSources(device)
  const services = device.services ?? []
  const visibleServices = services.slice(0, 4)
  const moreServices = services.length - visibleServices.length

  // Timestamps: a device placed on a canvas shows its linked node's lifecycle
  // (created / last scan / last modified / last seen). A device that is only in
  // the discovery inventory has no node yet, so it falls back to when the
  // scanner first saw it.
  const onCanvas = (device.canvas_count ?? 0) > 0
  const timestamps: { label: string; iso: string }[] = []
  if (onCanvas) {
    if (device.node_created_at) timestamps.push({ label: 'Created', iso: device.node_created_at })
    if (device.node_last_scan) timestamps.push({ label: 'Scan', iso: device.node_last_scan })
    if (device.node_last_modified) timestamps.push({ label: 'Modified', iso: device.node_last_modified })
    if (device.node_last_seen) timestamps.push({ label: 'Seen', iso: device.node_last_seen })
  }
  if (timestamps.length === 0) {
    timestamps.push({ label: 'Discovered', iso: device.discovered_at })
  }

  const borderClass = highlighted
    ? 'border-[#e3b341] bg-[#2d3748]'
    : selected
    ? 'border-[#00d4ff] bg-[#00d4ff]/5 shadow-[0_0_0_1px_rgba(0,212,255,0.4)] scale-[1.02]'
    : 'border-border bg-[#161b22] hover:border-[#30363d] hover:bg-[#21262d]'

  return (
    <button
      ref={cardRef}
      onClick={onClick}
      data-testid={`pending-card-${device.id}`}
      className={`relative text-left rounded-lg border p-2.5 transition-all duration-150 ${borderClass}`}
    >
      {selectMode && selected && (
        <CheckCircle2
          size={18}
          className="absolute top-2 right-2 text-[#00d4ff] fill-[#0d1117] z-10"
        />
      )}
      {!selectMode && device.status === 'hidden' && (
        <EyeOff size={14} className="absolute top-2 right-2 text-muted-foreground" />
      )}
      {/* Canvas-presence corner: how many canvases this device already sits on.
          Hidden while a select-mode checkmark occupies the same corner. */}
      {device.status !== 'hidden' && (device.canvas_count ?? 0) > 0 && !(selectMode && selected) && (
        <div
          className="absolute top-0 right-0 flex items-center gap-1 rounded-bl-lg rounded-tr-lg bg-[#00d4ff] text-[#0d1117] text-xs font-bold px-2 py-1 shadow-md"
          title={`On ${device.canvas_count} canvas${device.canvas_count !== 1 ? 'es' : ''}`}
          aria-label={`On ${device.canvas_count} canvas${device.canvas_count !== 1 ? 'es' : ''}`}
        >
          <Layers size={12} strokeWidth={2.5} />
          {device.canvas_count}
        </div>
      )}

      <div className="flex items-start gap-2 mb-2">
        <div className="shrink-0 w-8 h-8 rounded bg-[#21262d] flex items-center justify-center text-foreground">
          <Icon size={16} />
        </div>
        <div className="flex-1 min-w-0">
          <div className="text-sm font-medium text-foreground break-all leading-snug">{label}</div>
          <div className="flex items-center gap-1 mt-0.5 flex-wrap">
            {sourceBadges.map((bucket) => (
              <span
                key={bucket}
                className="text-[9px] font-mono px-1.5 py-0.5 rounded uppercase tracking-wider"
                style={{ background: `${SOURCE_META[bucket].color}22`, color: SOURCE_META[bucket].color }}
              >
                {SOURCE_META[bucket].label}
              </span>
            ))}
            {roleType !== 'generic' && (
              <span
                className="text-[9px] font-mono px-1.5 py-0.5 rounded uppercase tracking-wider"
                style={{ background: `${roleColor}22`, color: roleColor }}
              >
                {roleType}
              </span>
            )}
            {device.lqi != null && (
              <span className="text-[9px] font-mono px-1.5 py-0.5 rounded uppercase tracking-wider bg-[#21262d] text-muted-foreground">
                LQI {device.lqi}
              </span>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-x-2 gap-y-0.5 text-[11px] mb-2">
        {device.ip && <InfoLine label="IP" value={device.ip} />}
        {device.mac && <InfoLine label="MAC" value={device.mac} />}
        {device.ieee_address && <InfoLine label="IEEE" value={device.ieee_address} />}
        {device.hostname && <InfoLine label="Host" value={device.hostname} />}
        {device.vendor && <InfoLine label="Vendor" value={device.vendor} />}
        {device.model && <InfoLine label="Model" value={device.model} />}
      </div>

      {visibleServices.length > 0 && (
        <div className="flex items-center gap-1 flex-wrap">
          {visibleServices.map((s, i) => {
            const color = serviceColor(s.port, s.category)
            return (
              <span
                key={`${s.port}-${s.protocol}-${i}`}
                className="text-[9px] font-mono px-1.5 py-0.5 rounded uppercase tracking-wider"
                style={{ background: `${color}22`, color }}
                title={`${s.service_name ?? ''} (${s.protocol}/${s.port})`}
              >
                {s.service_name}
              </span>
            )
          })}
          {moreServices > 0 && (
            <span className="text-[9px] font-mono px-1.5 py-0.5 rounded bg-[#21262d] text-muted-foreground">
              +{moreServices}
            </span>
          )}
        </div>
      )}

      {/* Timestamps — compact relative times, full date on hover. Kept tiny so
          the tile footprint stays the same as before. */}
      <div className="mt-2 pt-2 border-t border-border/50 grid grid-cols-2 gap-x-2 gap-y-0.5 text-[10px]">
        {timestamps.map((t) => (
          <TimeLine key={t.label} label={t.label} iso={t.iso} />
        ))}
      </div>
    </button>
  )
}

function InfoLine({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-baseline gap-1.5 min-w-0">
      <span className="text-muted-foreground shrink-0 w-12">{label}</span>
      <span className="font-mono text-foreground truncate">{value}</span>
    </div>
  )
}

function TimeLine({ label, iso }: { label: string; iso: string }) {
  return (
    <div className="flex items-baseline gap-1 min-w-0" title={formatTimestamp(iso)}>
      <span className="text-muted-foreground shrink-0">{label}</span>
      <span className="font-mono text-foreground/80 truncate">{formatRelative(iso)}</span>
    </div>
  )
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { RefreshCw, X, Loader2, StopCircle, Clock, ScanLine, Network, RadioTower, Server, Inbox } from 'lucide-react'
import { Dialog, DialogClose, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { scanApi } from '@/api/client'
import { useCanvasStore } from '@/stores/canvasStore'
import { toast } from 'sonner'

export interface ScanRun {
  id: string
  status: string
  kind?: string
  ranges: string[]
  devices_found: number
  started_at: string
  finished_at: string | null
  error: string | null
}

interface ScanHistoryModalProps {
  open: boolean
  onClose: () => void
}

type KindFilter = 'all' | 'ip' | 'zigbee' | 'zwave' | 'proxmox'
type StatusFilter = 'all' | 'running' | 'done' | 'error' | 'cancelled'

/** Normalise a ScanRun.kind into one of the known display kinds. */
function runKind(kind: string | undefined): 'ip' | 'zigbee' | 'zwave' | 'proxmox' {
  return kind === 'zigbee' ? 'zigbee' : kind === 'zwave' ? 'zwave' : kind === 'proxmox' ? 'proxmox' : 'ip'
}

const KIND_META = {
  ip: { label: 'IP', color: '#a855f7' },
  zigbee: { label: 'Zigbee', color: '#00d4ff' },
  zwave: { label: 'Z-Wave', color: '#ff6e00' },
  proxmox: { label: 'Proxmox', color: '#e57000' },
} as const

const STATUS_FILTERS: { key: StatusFilter; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'running', label: 'Running' },
  { key: 'done', label: 'Done' },
  { key: 'error', label: 'Error' },
  { key: 'cancelled', label: 'Cancelled' },
]

const KIND_FILTERS: { key: KindFilter; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'ip', label: 'IP' },
  { key: 'zigbee', label: 'Zigbee' },
  { key: 'zwave', label: 'Z-Wave' },
  { key: 'proxmox', label: 'Proxmox' },
]

function statusColor(s: string): string {
  return s === 'done' ? '#39d353'
    : s === 'running' ? '#e3b341'
    : s === 'error' ? '#f85149'
    : s === 'cancelled' ? '#8b949e'
    : '#8b949e'
}

function parseUtc(ts: string): number {
  return new Date(ts.endsWith('Z') ? ts : ts + 'Z').getTime()
}

function formatDuration(ms: number): string {
  if (ms < 0) ms = 0
  const s = Math.floor(ms / 1000)
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  const rem = s % 60
  if (m < 60) return rem ? `${m}m ${rem}s` : `${m}m`
  const h = Math.floor(m / 60)
  return `${h}h ${m % 60}m`
}

function runDuration(r: ScanRun, now: number): string {
  const start = parseUtc(r.started_at)
  const end = r.finished_at ? parseUtc(r.finished_at) : now
  return formatDuration(end - start)
}

export function ScanHistoryModal({ open, onClose }: ScanHistoryModalProps) {
  const [runs, setRuns] = useState<ScanRun[]>([])
  const [loading, setLoading] = useState(false)
  const [stopping, setStopping] = useState<string | null>(null)
  const [kindFilter, setKindFilter] = useState<KindFilter>('all')
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all')
  const [now, setNow] = useState(() => Date.now())
  const prevRunsRef = useRef<ScanRun[]>([])

  const load = useCallback(async () => {
    setLoading(true)
    try {
      const res = await scanApi.runs()
      const next: ScanRun[] = res.data

      // Surface transitions and refresh dependent UI
      for (const run of next) {
        const prev = prevRunsRef.current.find((r) => r.id === run.id)
        if (prev?.status === 'running' && run.status === 'error') {
          toast.error(`Scan failed: ${run.error ?? 'unknown error'}`)
        }
        if (prev?.status === 'running' && run.status === 'done') {
          if (run.kind === 'proxmox' && run.error) {
            // A done Proxmox run carrying a non-fatal advisory (e.g. hosts
            // imported but no guests visible) is a warning, not a success.
            toast.warning(run.error)
          } else if (run.kind === 'zigbee' || run.kind === 'zwave' || run.kind === 'proxmox') {
            const label = run.kind === 'zwave' ? 'Z-Wave' : run.kind === 'proxmox' ? 'Proxmox' : 'Zigbee'
            toast.success(`${label} import done — ${run.devices_found} device${run.devices_found !== 1 ? 's' : ''}`)
          }
          useCanvasStore.getState().notifyScanDeviceFound()
        }
      }
      prevRunsRef.current = next
      setRuns(next)
    } catch {
      toast.error('Failed to load scan history')
    } finally {
      setLoading(false)
    }
  }, [])

  // Load when opened; reset prior-state tracker so we don't replay old transitions
  useEffect(() => {
    if (!open) return
    prevRunsRef.current = []
    load()
  }, [open, load])

  // Auto-refresh every 3s while any run is still running (only when open)
  useEffect(() => {
    if (!open) return
    const hasRunning = runs.some((r) => r.status === 'running')
    if (!hasRunning) return
    const id = setInterval(load, 3000)
    return () => clearInterval(id)
  }, [open, runs, load])

  // Tick the clock every second while a scan is running (for live elapsed duration)
  useEffect(() => {
    if (!open) return
    const hasRunning = runs.some((r) => r.status === 'running')
    if (!hasRunning) return
    const id = setInterval(() => setNow(Date.now()), 1000)
    return () => clearInterval(id)
  }, [open, runs])

  const handleStop = async (runId: string) => {
    setStopping(runId)
    try {
      await scanApi.stop(runId)
      toast.success('Scan stop requested')
    } catch {
      toast.error('Failed to stop scan')
    } finally {
      setStopping(null)
    }
  }

  const filtered = runs.filter((r) => {
    const k = runKind(r.kind)
    if (kindFilter !== 'all' && k !== kindFilter) return false
    if (statusFilter !== 'all' && r.status !== statusFilter) return false
    return true
  })

  return (
    <Dialog open={open} onOpenChange={(v) => { if (!v) onClose() }}>
      <DialogContent
        showCloseButton={false}
        className="!max-w-none w-[90vw] max-w-2xl h-[80vh] p-0 flex flex-col gap-0 bg-[#0d1117] border-border"
      >
        <DialogHeader className="px-4 py-3 border-b border-border shrink-0">
          <div className="flex items-center justify-between gap-3">
            <DialogTitle className="text-base font-semibold flex items-center gap-2">
              <Clock size={16} className="text-[#00d4ff]" />
              Scan History
              <span className="text-muted-foreground font-normal text-xs">
                ({filtered.length}{filtered.length !== runs.length && ` of ${runs.length}`})
              </span>
            </DialogTitle>
            <div className="flex items-center gap-1">
              <button onClick={load} className="text-muted-foreground hover:text-foreground p-1.5 rounded transition-colors" title="Refresh">
                <RefreshCw size={14} className={loading ? 'animate-spin' : undefined} />
              </button>
              <DialogClose
                render={
                  <button
                    className="text-muted-foreground hover:text-foreground p-1.5 rounded transition-colors"
                    aria-label="Close"
                  />
                }
              >
                <X size={14} />
              </DialogClose>
            </div>
          </div>
        </DialogHeader>

        {/* Filters */}
        <div className="px-4 py-2 border-b border-border bg-[#161b22] shrink-0 flex flex-wrap items-center gap-x-4 gap-y-2">
          <div className="flex items-center gap-1.5">
            <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">Type</span>
            {KIND_FILTERS.map((f) => (
              <FilterChip key={f.key} active={kindFilter === f.key} onClick={() => setKindFilter(f.key)}>
                {f.label}
              </FilterChip>
            ))}
          </div>
          <div className="flex items-center gap-1.5">
            <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">Status</span>
            {STATUS_FILTERS.map((f) => (
              <FilterChip key={f.key} active={statusFilter === f.key} onClick={() => setStatusFilter(f.key)}>
                {f.label}
              </FilterChip>
            ))}
          </div>
        </div>

        {/* List */}
        <div className="flex-1 min-h-0 overflow-y-auto p-3 space-y-2">
          {loading && runs.length === 0 && (
            <div className="flex justify-center py-10">
              <Loader2 size={18} className="animate-spin text-muted-foreground" />
            </div>
          )}
          {!loading && filtered.length === 0 && (
            <div className="flex flex-col items-center gap-2 py-12 text-muted-foreground">
              <Inbox size={28} className="opacity-50" />
              <p className="text-sm">{runs.length === 0 ? 'No scans yet' : 'No scans match the filters'}</p>
            </div>
          )}
          {filtered.map((r) => {
            const kind = runKind(r.kind)
            const meta = KIND_META[kind]
            const KindIcon = kind === 'zigbee' ? Network : kind === 'zwave' ? RadioTower : kind === 'proxmox' ? Server : ScanLine
            // A done run carrying a non-fatal advisory renders amber (info),
            // distinct from a red error.
            const advisory = r.status === 'done' && !!r.error
            const dotColor = advisory ? '#e3b341' : statusColor(r.status)
            return (
              <div key={r.id} className="rounded-lg border border-border bg-[#161b22] p-3">
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: dotColor }} />
                  <span className="font-mono text-sm text-foreground capitalize">{r.status}</span>
                  {r.status === 'running' && <Loader2 size={12} className="animate-spin text-[#e3b341]" />}
                  <span
                    className="inline-flex items-center gap-1 text-[10px] font-mono px-1.5 py-0.5 rounded uppercase tracking-wider"
                    style={{ background: `${meta.color}22`, color: meta.color }}
                  >
                    <KindIcon size={10} />
                    {meta.label}
                  </span>
                  <span className="ml-auto text-xs text-muted-foreground font-mono">
                    {r.devices_found} found
                  </span>
                  {r.status === 'running' && (
                    <Tooltip>
                      <TooltipTrigger>
                        <button
                          aria-label="Stop scan"
                          onClick={() => handleStop(r.id)}
                          disabled={stopping === r.id}
                          className="p-1 text-[#f85149] hover:bg-[#f85149]/10 rounded transition-colors disabled:opacity-50"
                        >
                          {stopping === r.id
                            ? <Loader2 size={13} className="animate-spin" />
                            : <StopCircle size={13} />}
                        </button>
                      </TooltipTrigger>
                      <TooltipContent side="left">Stop scan</TooltipContent>
                    </Tooltip>
                  )}
                </div>

                {/* Meta grid */}
                <div className="mt-2 grid grid-cols-2 gap-x-4 gap-y-1 text-[11px]">
                  <Meta label="Started" value={new Date(parseUtc(r.started_at)).toLocaleString()} />
                  <Meta
                    label="Finished"
                    value={r.finished_at ? new Date(parseUtc(r.finished_at)).toLocaleString() : '—'}
                  />
                  <Meta label="Duration" value={runDuration(r, now)} mono />
                  <Meta label="Devices" value={`${r.devices_found}`} mono />
                </div>

                {r.ranges.length > 0 && (
                  <div className="mt-2 text-[11px]">
                    <span className="text-muted-foreground">Ranges: </span>
                    <span className="text-[#8b949e] font-mono break-all">{r.ranges.join(', ')}</span>
                  </div>
                )}

                {r.error && (
                  <div className={`mt-2 text-[11px] leading-tight whitespace-pre-wrap break-words rounded px-2 py-1.5 ${
                    advisory
                      ? 'text-[#e3b341] bg-[#e3b341]/10'
                      : 'text-[#f85149] bg-[#f85149]/10'
                  }`}>
                    {r.error}
                  </div>
                )}
              </div>
            )
          })}
        </div>
      </DialogContent>
    </Dialog>
  )
}

function FilterChip({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      onClick={onClick}
      className={`text-[11px] px-2 py-0.5 rounded-full border transition-colors cursor-pointer ${
        active
          ? 'bg-[#00d4ff]/10 border-[#00d4ff]/40 text-[#00d4ff]'
          : 'border-border text-muted-foreground hover:text-foreground hover:border-[#30363d]'
      }`}
    >
      {children}
    </button>
  )
}

function Meta({ label, value, mono }: { label: string; value: string; mono?: boolean }) {
  return (
    <div className="flex flex-col">
      <span className="text-muted-foreground text-[10px] uppercase tracking-wider">{label}</span>
      <span className={`text-foreground ${mono ? 'font-mono' : ''}`}>{value}</span>
    </div>
  )
}

import { useState, useCallback, useEffect } from 'react'
import { Plus, Save, ScanLine, ChevronLeft, ChevronRight, LayoutDashboard, Clock, EyeOff, Square, Eye, Radio, RadioTower, Server, Type, PlusCircle, Pencil, Trash2, Map, Rows3 } from 'lucide-react'
import { Logo } from '@/components/ui/Logo'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { useCanvasStore } from '@/stores/canvasStore'
import { useDesignStore } from '@/stores/designStore'
import { designsApi, mediaApi } from '@/api/client'
import { resolveDesignIcon, DEFAULT_DESIGN_ICON } from '@/utils/designIcons'
import { DesignModal, type DesignFormData } from '@/components/modals/DesignModal'
import type { Design } from '@/types'
import { AccessoryTray } from '@/rack/components/AccessoryTray'
import { useRackStore } from '@/rack/store'
import { freeUnits } from '@/rack/layout'
import { toast } from 'sonner'
import { useLatestRelease } from '@/hooks/useLatestRelease'

import { PendingDevicesModal } from '@/components/modals/PendingDevicesModal'
import { ScanHistoryModal } from '@/components/modals/ScanHistoryModal'
import { ZigbeeImportModal } from '@/components/zigbee/ZigbeeImportModal'
import { ZwaveImportModal } from '@/components/zwave/ZwaveImportModal'
import { ProxmoxImportModal } from '@/components/proxmox/ProxmoxImportModal'
import { buildProxmoxClusterEdges } from '@/components/proxmox/clusterEdges'
import type { ProxmoxNode, ProxmoxEdge } from '@/components/proxmox/types'
import { getCenteredPosition } from '@/utils/viewportCenter'
import type { NodeData } from '@/types'
import type { Node, Connection } from '@xyflow/react'

const STANDALONE = import.meta.env.VITE_STANDALONE === 'true'

type SidebarView = 'canvas' | 'pending' | 'hidden' | 'history'

const ALL_VIEWS = [
  { id: 'canvas' as SidebarView, icon: LayoutDashboard, label: 'Canvas' },
  { id: 'pending' as SidebarView, icon: ScanLine, label: 'Device Inventory' },
  { id: 'hidden' as SidebarView, icon: EyeOff, label: 'Hidden Devices' },
  { id: 'history' as SidebarView, icon: Clock, label: 'Scan History' },
]
const VIEWS = STANDALONE ? ALL_VIEWS.slice(0, 1) : ALL_VIEWS

interface SidebarProps {
  onAddNode: () => void
  onAddGroupRect: () => void
  onAddText: () => void
  onScan: () => void
  onSave: () => void
  onNodeApproved: (nodeId: string) => void
  forceView?: SidebarView
  onClearForceView?: () => void
  highlightPendingId?: string
}

export function Sidebar({ onAddNode, onAddGroupRect, onAddText, onScan, onSave, onNodeApproved: _onNodeApproved, forceView, onClearForceView, highlightPendingId }: SidebarProps) {
  const [_collapsed, setCollapsed] = useState(false)
  const [_activeView, setActiveView] = useState<SidebarView>('canvas')
  const [zigbeeOpen, setZigbeeOpen] = useState(false)
  const [zwaveOpen, setZwaveOpen] = useState(false)
  const [proxmoxOpen, setProxmoxOpen] = useState(false)
  const [pendingModalOpen, setPendingModalOpen] = useState(false)
  const [pendingModalStatus, setPendingModalStatus] = useState<'pending' | 'hidden'>('pending')
  const [scanHistoryOpen, setScanHistoryOpen] = useState(false)

  // When forceView is set, override local state without useEffect
  const collapsed = forceView ? false : _collapsed
  const activeView = forceView ?? _activeView

  const { nodes, hasUnsavedChanges: canvasDirty, hideIp, toggleHideIp, addNode, onConnect, snapshotHistory, markUnsaved, floorMap, setFloorMap } = useCanvasStore()
  const floorMapEditNonce = useCanvasStore((s) => s.floorMapEditNonce)
  // A rack design swaps the canvas actions for rack ones, and its own store
  // owns the unsaved-changes badge.
  const isRack = useDesignStore((s) => s.activeDesignType) === 'rack'
  const rackDirty = useRackStore((s) => s.hasUnsavedChanges)
  const openDeviceEditor = useRackStore((s) => s.openDeviceEditor)
  const hasUnsavedChanges = isRack ? rackDirty : canvasDirty

  // Direct "Add to Canvas" for a Proxmox import: drop the selected hosts/guests
  // as typed nodes and wire host→guest 'virtual' + host↔host 'cluster' edges.
  const handleProxmoxAddToCanvas = useCallback((pmNodes: ProxmoxNode[], pmEdges: ProxmoxEdge[]) => {
    snapshotHistory()
    const COLS = 4
    const SPACING_X = 190
    const SPACING_Y = 110
    const cols = Math.min(COLS, pmNodes.length)
    const rows = Math.ceil(pmNodes.length / COLS)
    const origin = getCenteredPosition(cols * SPACING_X, rows * SPACING_Y)
    // Multiple hosts from one import = a cluster → chain them via left/right
    // 'cluster' edges. Those endpoints need one left + one right handle each
    // (both default to 0), so grant them to the host nodes up front.
    const clusterEdges = buildProxmoxClusterEdges(pmNodes)
    const cluster = clusterEdges.length > 0
    pmNodes.forEach((pn, i) => {
      const col = i % COLS
      const row = Math.floor(i / COLS)
      const position = { x: origin.x + col * SPACING_X, y: origin.y + row * SPACING_Y }
      const isClusterHost = cluster && pn.type === 'proxmox'
      const newNode: Node<NodeData> = {
        id: pn.id,
        type: pn.type,
        position,
        data: {
          label: pn.label,
          type: pn.type as NodeData['type'],
          status: (pn.status === 'online' ? 'online' : 'unknown') as NodeData['status'],
          services: [],
          // The import already upserted the Device Inventory row; carry its id so
          // the canvas save links to that row instead of minting a second one.
          ...(pn.device_id ? { device_id: pn.device_id } : {}),
          ...(pn.ip ? { ip: pn.ip } : {}),
          ...(pn.hostname ? { hostname: pn.hostname } : {}),
          ...(isClusterHost ? { left_handles: 1, right_handles: 1 } : {}),
        },
      }
      addNode(newNode)
    })
    // Host → guest links render as 'virtual' edges (VM/LXC ↔ host).
    pmEdges.forEach((pe) => {
      onConnect({
        source: pe.source,
        sourceHandle: 'bottom',
        target: pe.target,
        targetHandle: 'top-t',
        type: 'virtual',
      } as unknown as Connection)
    })
    // Host ↔ host links render as 'cluster' edges (left → right chain).
    clusterEdges.forEach((ce) => {
      onConnect({
        source: ce.source,
        sourceHandle: ce.sourceHandle,
        target: ce.target,
        targetHandle: ce.targetHandle,
        type: 'cluster',
      } as unknown as Connection)
    })
    markUnsaved()
  }, [addNode, onConnect, snapshotHistory, markUnsaved])
  const { designs, activeDesignId, setActiveDesign, addDesign, updateDesign, removeDesign } = useDesignStore()
  const [designSwitcherOpen, setDesignSwitcherOpen] = useState(false)
  const [designModal, setDesignModal] = useState<{ mode: 'create' | 'edit'; design?: Design } | null>(null)
  // Bumped on every open so the modal remounts and re-seeds its local state from
  // the current floor plan — otherwise a reopen keeps stale width/height/lock
  // and Save would clobber a canvas-side resize/move.
  const [openSeq, setOpenSeq] = useState(0)

  const openDesignModal = useCallback((m: { mode: 'create' | 'edit'; design?: Design }) => {
    setOpenSeq((s) => s + 1)
    setDesignModal(m)
  }, [])

  const handleDesignSubmit = useCallback(async (data: DesignFormData) => {
    if (!designModal) return
    try {
      if (designModal.mode === 'create') {
        // Copy from an existing canvas (nodes, edges, viewport) when a source is
        // picked; otherwise start blank.
        const res = data.sourceId
          ? await designsApi.copy(data.sourceId, { name: data.name, icon: data.icon })
          : await designsApi.create({ name: data.name, icon: data.icon, design_type: data.designType ?? 'network' })
        addDesign(res.data)
      } else if (designModal.design) {
        const res = await designsApi.update(designModal.design.id, { name: data.name, icon: data.icon })
        updateDesign(res.data.id, { name: res.data.name, icon: res.data.icon })
      }
      // Floor plan is canvas data attached to the active design. `undefined`
      // means the section wasn't shown → leave it untouched. Applied to the
      // store and persisted on the next explicit canvas Save.
      if (data.floorMap !== undefined) {
        setFloorMap(data.floorMap)
      }
      setDesignModal(null)
    } catch {
      toast.error(designModal.mode === 'create' ? 'Failed to create canvas' : 'Failed to update canvas')
    }
  }, [designModal, addDesign, updateDesign, setFloorMap])

  const handleUploadImage = useCallback(async (file: File): Promise<string> => {
    try {
      const { url } = await mediaApi.upload(file)
      return url
    } catch {
      toast.error('Image upload failed')
      throw new Error('upload failed')
    }
  }, [])

  const isActiveEdit = designModal?.mode === 'edit' && designModal.design?.id === activeDesignId

  // Double-click on the floor plan (canvas) asks to edit the active canvas.
  useEffect(() => {
    if (floorMapEditNonce === 0) return
    const active = designs.find((d) => d.id === activeDesignId)
    if (active) openDesignModal({ mode: 'edit', design: active })
    // Only react to the nonce bump, not to design/active changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [floorMapEditNonce])

  // "Add Floorplan" opens the active canvas's edit modal, where the floor plan
  // section lives (it's gated to the active design — see isActiveEdit).
  const openFloorPlan = useCallback(() => {
    const active = designs.find((d) => d.id === activeDesignId)
    if (active) openDesignModal({ mode: 'edit', design: active })
  }, [designs, activeDesignId, openDesignModal])

  const handleDesignDelete = useCallback(async (d: Design) => {
    if (designs.length <= 1) { toast.error('Cannot delete the only canvas'); return }
    if (!window.confirm(`Delete canvas "${d.name}"? Its nodes and links will be removed.`)) return
    try {
      await designsApi.delete(d.id)
      removeDesign(d.id)
      toast.success('Canvas deleted')
    } catch {
      toast.error('Failed to delete canvas')
    }
  }, [designs.length, removeDesign])

  const networkNodes = nodes.filter((n) => n.data.type !== 'groupRect' && n.data.type !== 'text')
  const onlineCount = networkNodes.filter((n) => n.data.status === 'online').length
  const offlineCount = networkNodes.filter((n) => n.data.status === 'offline').length

  const handleScan = useCallback(() => {
    onScan()
  }, [onScan])

  return (
    <aside
      className="flex flex-col border-r border-border bg-[#161b22] transition-all duration-200 relative shrink-0"
      style={{ width: collapsed ? 48 : 220 }}
    >
      {/* Toggle */}
      <button
        onClick={() => setCollapsed((c) => !c)}
        className="absolute -right-3 top-6 z-10 flex items-center justify-center w-6 h-6 rounded-full border border-border bg-[#21262d] text-muted-foreground hover:text-foreground transition-colors"
      >
        {collapsed ? <ChevronRight size={12} /> : <ChevronLeft size={12} />}
      </button>

      {/* Logo */}
      <div className="flex items-center px-3 py-4 border-b border-border overflow-hidden">
        <Logo size={28} showText={!collapsed} />
      </div>

      {/* Design (canvas) switcher */}
      {!collapsed && designs.length > 0 && (
        <div className="px-2 pt-2 pb-1 border-b border-border relative">
          <button
            onClick={() => setDesignSwitcherOpen((o) => !o)}
            className="flex items-center gap-2 w-full px-2 py-1.5 rounded-md text-xs font-medium bg-[#21262d] border border-border hover:border-[#30363d] transition-colors cursor-pointer"
          >
            {activeDesignId ? (() => {
              const active = designs.find((d) => d.id === activeDesignId)
              const Icon = resolveDesignIcon(active?.icon)
              return <><Icon size={14} className="shrink-0 text-[#00d4ff]" /><span className="truncate text-foreground">{active?.name ?? 'Select Canvas'}</span></>
            })() : <span className="text-muted-foreground">Select Canvas</span>}
          </button>
          {designSwitcherOpen && (
            <>
              {/* Overlay to close */}
              <div className="fixed inset-0 z-40" onClick={() => setDesignSwitcherOpen(false)} />
              <div className="absolute left-2 right-2 top-full mt-1 z-50 bg-[#21262d] border border-border rounded-md shadow-xl overflow-hidden">
                {designs.map((d) => {
                  const Icon = resolveDesignIcon(d.icon)
                  const isActive = d.id === activeDesignId
                  return (
                    <div
                      key={d.id}
                      className={`group flex items-center transition-colors ${
                        isActive ? 'bg-[#00d4ff]/10 text-[#00d4ff]' : 'text-muted-foreground hover:bg-[#30363d]'
                      }`}
                    >
                      <button
                        onClick={() => { setActiveDesign(d.id); setDesignSwitcherOpen(false) }}
                        className="flex items-center gap-2 flex-1 min-w-0 px-3 py-2 text-xs cursor-pointer hover:text-foreground"
                      >
                        <Icon size={14} className="shrink-0" />
                        <span className="truncate">{d.name}</span>
                      </button>
                      <button
                        aria-label={`Edit ${d.name}`}
                        title="Edit canvas"
                        onClick={() => { openDesignModal({ mode: 'edit', design: d }); setDesignSwitcherOpen(false) }}
                        className="shrink-0 p-1.5 text-muted-foreground hover:text-foreground cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <Pencil size={12} />
                      </button>
                      <button
                        aria-label={`Delete ${d.name}`}
                        title="Delete canvas"
                        disabled={designs.length <= 1}
                        onClick={() => handleDesignDelete(d)}
                        className="shrink-0 p-1.5 pr-2 text-muted-foreground hover:text-[#f85149] cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity disabled:opacity-0"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  )
                })}
                <div className="border-t border-border" />
                <button
                  onClick={() => { openDesignModal({ mode: 'create' }); setDesignSwitcherOpen(false) }}
                  className="flex items-center gap-2 w-full px-3 py-2 text-xs text-[#00d4ff] hover:bg-[#00d4ff]/10 transition-colors cursor-pointer"
                >
                  <PlusCircle size={14} />
                  <span>New Canvas</span>
                </button>
              </div>
            </>
          )}
        </div>
      )}

      {/* Views */}
      <nav className="flex flex-col gap-0.5 p-2">
        {VIEWS.map(({ id, icon: Icon, label }) => (
          <SidebarItem
            key={id}
            icon={id === 'canvas' && isRack ? Rows3 : Icon}
            label={id === 'canvas' && isRack ? 'Rack view' : label}
            collapsed={collapsed}
            active={activeView === id}
            onClick={() => {
              onClearForceView?.()
              if (id === 'pending') {
                setPendingModalStatus('pending')
                setPendingModalOpen(true)
                return
              }
              if (id === 'hidden') {
                setPendingModalStatus('hidden')
                setPendingModalOpen(true)
                return
              }
              if (id === 'history') {
                setScanHistoryOpen(true)
                return
              }
              setActiveView(id)
            }}
          />
        ))}
      </nav>

      {/* Spacer — pending / hidden / history all open in modals. On a rack
          canvas the accessory tray takes the space: it scrolls, everything
          else stays pinned. */}
      {isRack && !collapsed ? <AccessoryTray /> : !collapsed && <div className="flex-1" />}

      {/* Stats footer */}
      {!collapsed && isRack && <RackStats />}
      {!collapsed && !isRack && (
        <div className="px-3 py-2 border-t border-border text-xs text-muted-foreground space-y-0.5">
          <div className="flex justify-between">
            <span>Total</span>
            <span className="text-foreground font-mono">{networkNodes.length}</span>
          </div>
          <div className="flex justify-between">
            <span className="text-[#39d353]">Online</span>
            <span className="font-mono text-[#39d353]">{onlineCount}</span>
          </div>
          <div className="flex justify-between">
            <span className="text-[#f85149]">Offline</span>
            <span className="font-mono text-[#f85149]">{offlineCount}</span>
          </div>
        </div>
      )}

      {/* Actions */}
      <div className="flex flex-col gap-0.5 p-2 border-t border-border">
        {isRack ? (
          <SidebarItem icon={Plus} label="Add Device" collapsed={collapsed} onClick={() => openDeviceEditor()} />
        ) : (
          <>
            <SidebarItem icon={Plus} label="Add Node" collapsed={collapsed} onClick={onAddNode} />
            <SidebarItem icon={Square} label="Add Zone" collapsed={collapsed} onClick={onAddGroupRect} />
            <SidebarItem icon={Type} label="Add Text" collapsed={collapsed} onClick={onAddText} />
            {!STANDALONE && <SidebarItem icon={ScanLine} label="Scan Network" collapsed={collapsed} onClick={handleScan} />}
            <SidebarItem icon={Radio} label="Import Zigbee" collapsed={collapsed} onClick={() => setZigbeeOpen(true)} />
            <SidebarItem icon={RadioTower} label="Import Z-Wave" collapsed={collapsed} onClick={() => setZwaveOpen(true)} />
            {!STANDALONE && <SidebarItem icon={Server} label="Import Proxmox" collapsed={collapsed} onClick={() => setProxmoxOpen(true)} />}
            {!STANDALONE && <SidebarItem icon={Map} label="Add Floorplan" collapsed={collapsed} onClick={openFloorPlan} />}
            <SidebarItem
              icon={hideIp ? EyeOff : Eye}
              label={hideIp ? 'Show IPs' : 'Hide IPs'}
              collapsed={collapsed}
              onClick={toggleHideIp}
              active={hideIp}
            />
          </>
        )}
        <SidebarItem
          icon={Save}
          label={isRack ? 'Save Rack' : 'Save Canvas'}
          collapsed={collapsed}
          onClick={() => onSave()}
          badge={hasUnsavedChanges}
          accent
        />
      </div>

      {!collapsed && <VersionBadge />}

      <ZigbeeImportModal
        open={zigbeeOpen}
        onClose={() => setZigbeeOpen(false)}
        onImported={() => {
          // Import runs in the background — surface it under Scan History
          // (running → done), mirroring the IP scan flow.
          setScanHistoryOpen(true)
        }}
      />
      <ZwaveImportModal
        open={zwaveOpen}
        onClose={() => setZwaveOpen(false)}
        onImported={() => {
          setScanHistoryOpen(true)
        }}
      />
      <ProxmoxImportModal
        open={proxmoxOpen}
        onClose={() => setProxmoxOpen(false)}
        onAddToCanvas={handleProxmoxAddToCanvas}
        onPendingImported={() => {
          // Background import — surface it under Scan History (running → done).
          setScanHistoryOpen(true)
        }}
      />
      <PendingDevicesModal
        open={pendingModalOpen}
        onClose={() => setPendingModalOpen(false)}
        highlightId={highlightPendingId}
        initialStatus={pendingModalStatus}
      />
      <ScanHistoryModal
        open={scanHistoryOpen}
        onClose={() => setScanHistoryOpen(false)}
      />

      <DesignModal
        key={`${designModal?.mode === 'edit' ? designModal.design?.id : 'create'}-${openSeq}`}
        open={!!designModal}
        onClose={() => setDesignModal(null)}
        onSubmit={handleDesignSubmit}
        initial={designModal?.mode === 'edit' && designModal.design
          ? { name: designModal.design.name, icon: designModal.design.icon ?? DEFAULT_DESIGN_ICON }
          : undefined}
        title={designModal?.mode === 'edit' ? 'Edit Canvas' : 'New Canvas'}
        submitLabel={designModal?.mode === 'edit' ? 'Save' : 'Create'}
        sourceDesigns={designModal?.mode === 'create' ? designs : []}
        // A rack canvas has no floor plan to lay under it.
        showFloorMap={!STANDALONE && isActiveEdit && !isRack}
        initialFloorMap={!STANDALONE && isActiveEdit ? floorMap : null}
        onUploadImage={handleUploadImage}
      />
    </aside>
  )
}

/** Rack equivalent of the node stats footer: capacity rather than reachability. */
function RackStats() {
  const racks = useRackStore((s) => s.racks)
  const devices = useRackStore((s) => s.devices)
  const cables = useRackStore((s) => s.cables)

  const free = racks.reduce((sum, rack) => sum + freeUnits(rack, devices), 0)
  const total = racks.reduce((sum, rack) => sum + rack.uHeight, 0)

  return (
    <div className="px-3 py-2 border-t border-border text-xs text-muted-foreground space-y-0.5">
      <div className="flex justify-between">
        <span>Racks</span>
        <span className="text-foreground font-mono">{racks.length}</span>
      </div>
      <div className="flex justify-between">
        <span>Mounted</span>
        <span className="text-foreground font-mono">{devices.length}</span>
      </div>
      <div className="flex justify-between">
        <span>Cables</span>
        <span className="text-foreground font-mono">{cables.length}</span>
      </div>
      <div className="flex justify-between">
        <span className="text-[#39d353]">Free</span>
        <span className="font-mono text-[#39d353]">{free}U / {total}U</span>
      </div>
    </div>
  )
}

function VersionBadge() {
  const current = __APP_VERSION__
  const { latest, hasUpdate } = useLatestRelease(current)

  return (
    <div className="px-3 py-2 border-t border-border flex flex-col gap-1">
      <a
        href={`https://github.com/Pouzor/homelable/releases/tag/v${current}`}
        target="_blank"
        rel="noopener noreferrer"
        className="font-mono text-[11px] text-muted-foreground hover:text-foreground transition-colors"
      >
        v{current}
      </a>
      {hasUpdate && latest && (
        <a
          href={latest.url.startsWith('https://') ? latest.url : '#'}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-[#e3b341]/15 text-[#e3b341] border border-[#e3b341]/30 hover:bg-[#e3b341]/25 transition-colors self-start"
        >
          ↑ v{latest.version} available
        </a>
      )}
    </div>
  )
}


interface SidebarItemProps {
  icon: React.ElementType
  label: string
  collapsed: boolean
  active?: boolean
  badge?: boolean
  accent?: boolean
  onClick?: () => void
}

function SidebarItem({ icon: Icon, label, collapsed, active, badge, accent, onClick }: SidebarItemProps) {
  const btn = (
    <button
      onClick={onClick}
      className={`relative flex items-center gap-2 w-full px-2 py-1.5 rounded-md text-sm transition-colors cursor-pointer ${
        active
          ? 'bg-[#00d4ff]/10 text-[#00d4ff]'
          : accent
          ? 'text-[#00d4ff] hover:bg-[#00d4ff]/10'
          : 'text-muted-foreground hover:text-foreground hover:bg-[#21262d]'
      }`}
    >
      <Icon size={16} className="shrink-0" />
      {!collapsed && <span className="truncate">{label}</span>}
      {badge && (
        <span className="absolute top-1 right-1 w-1.5 h-1.5 rounded-full bg-[#e3b341]" />
      )}
    </button>
  )

  if (collapsed) {
    return (
      <Tooltip>
        <TooltipTrigger>{btn}</TooltipTrigger>
        <TooltipContent side="right">{label}</TooltipContent>
      </Tooltip>
    )
  }

  return btn
}

/**
 * Add / edit a mounted device.
 *
 * The rack canvas has no right rail: everything about a mount is edited here,
 * the way `NodeModal` owns a network node. Opened from the sidebar (`+ Device`)
 * or by double-clicking a plate.
 *
 * Creating offers the two sources the product recognises: an entry that already
 * exists in the **Device Inventory**, or a brand new one created from this
 * canvas (which lands in the inventory too). Accessories — blanks, shelves,
 * cable managers — are rack-only and never touch the inventory.
 */
import { useEffect, useMemo, useState } from 'react'
import { toast } from 'sonner'
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { PendingDevicesModal } from '@/components/modals/PendingDevicesModal'
import type { PendingDevice } from '@/components/modals/PendingDeviceModal'
import { useRackStore } from '../store'
import { FaceplatePicker } from './FaceplatePicker'
import { PortListEditor } from './PortListEditor'
import { PortPositionEditor } from './PortPositionEditor'
import { LinkedDevicePanel } from './LinkedDevicePanel'
import { SectionHeader } from './SectionHeader'
import { DevicePickerModal } from './DevicePickerModal'
import { deviceTypeForFaceplate, getFaceplate } from '../faceplates'
import { findSlot } from '../layout'
import { canFollowNode, resolveDeviceStatus } from '../deviceStatus'
import { generateUUID } from '@/utils/uuid'
import {
  RACK_COLUMNS,
  type InventoryDevice,
  type MountStatus,
  type Port,
  type PortVisibility,
} from '@/types'

const DEFAULT_COLOR = '#2b323c'

type Source = 'inventory' | 'new' | 'accessory'

const inputBase =
  'rounded border border-[#30363d] bg-[#21262d] px-2 py-1 text-sm text-foreground outline-none focus:border-[#00d4ff]'
const inputClass = `w-full ${inputBase}`
const fieldLabel = 'text-xs text-muted-foreground'

/**
 * One line for the inventory picker.
 *
 * Entries with no hostname are already labelled with their IP by the backend, so
 * appending it again printed "192.168.1.63 · 192.168.1.63". Show the IP only
 * when it adds something, and the type as the tiebreaker between look-alikes.
 */
function inventoryOption(item: InventoryDevice): string {
  const parts = [item.label]
  if (item.ip && item.ip !== item.label) parts.push(item.ip)
  if (item.type) parts.push(item.type)
  return parts.join(' · ')
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex flex-col gap-1.5">
      <Label className={fieldLabel}>{label}</Label>
      {children}
    </div>
  )
}

export function RackDeviceModal() {
  const editor = useRackStore((s) => s.deviceEditor)
  const close = useRackStore((s) => s.closeDeviceEditor)
  if (!editor) return null
  // Remount per target so the form always re-seeds from the device it edits.
  return <DeviceForm key={editor.deviceId ?? 'new'} deviceId={editor.deviceId} onClose={close} />
}

function DeviceForm({ deviceId, onClose }: { deviceId: string | null; onClose: () => void }) {
  const device = useRackStore((s) => s.devices.find((d) => d.id === deviceId))
  const racks = useRackStore((s) => s.racks)
  const devices = useRackStore((s) => s.devices)
  const inventory = useRackStore((s) => s.inventory)
  const mountFromInventory = useRackStore((s) => s.mountFromInventory)
  const mountAccessory = useRackStore((s) => s.mountAccessory)
  const createInventoryDevice = useRackStore((s) => s.createInventoryDevice)
  const applyFaceplate = useRackStore((s) => s.applyFaceplate)
  const updateDevice = useRackStore((s) => s.updateDevice)
  const relinkDevice = useRackStore((s) => s.relinkDevice)
  const unmountDevice = useRackStore((s) => s.unmountDevice)
  const setPorts = useRackStore((s) => s.setPorts)

  const isEdit = !!device
  const unracked = useMemo(() => inventory.filter((i) => !i.racked), [inventory])

  const [source, setSource] = useState<Source>(unracked.length > 0 ? 'inventory' : 'new')
  // No preselection: the entry comes from the Device Inventory modal, which the
  // user opens and picks from explicitly.
  const [inventoryId, setInventoryId] = useState('')
  const [newIp, setNewIp] = useState('')
  const [rackId, setRackId] = useState(device?.rackId ?? racks[0]?.id ?? '')
  const [label, setLabel] = useState(device?.label ?? '')
  const [faceplateId, setFaceplateId] = useState(device?.faceplateId ?? 'server-1u')
  const [uStart, setUStart] = useState(device?.uStart ?? 1)
  const [uHeight, setUHeight] = useState(device?.uHeight ?? getFaceplate(faceplateId).uHeight)
  const [colStart, setColStart] = useState(device?.colStart ?? 0)
  const [colSpan, setColSpan] = useState(device?.colSpan ?? getFaceplate(faceplateId).colSpan)
  const [status, setStatus] = useState<MountStatus>(device?.status ?? 'unknown')
  const [color, setColor] = useState<string | undefined>(device?.color)
  const [portVisibility, setPortVisibility] = useState<PortVisibility>(
    device?.portVisibility ?? 'auto',
  )
  const [ports, setLocalPorts] = useState<Port[]>(
    device?.ports ?? getFaceplate(faceplateId).ports.map((p) => ({ ...p, id: generateUUID() })),
  )
  /** Drag mode on the plate below the form. Off by default: most edits are text. */
  const [positioning, setPositioning] = useState(false)
  /** Highlighted port, shared between the list and the plate. */
  const [selectedPortId, setSelectedPortId] = useState<string | null>(null)
  const [plateChanged, setPlateChanged] = useState(false)
  const [pickerOpen, setPickerOpen] = useState(false)
  const [inventoryPickerOpen, setInventoryPickerOpen] = useState(false)
  const [devicePickerOpen, setDevicePickerOpen] = useState(false)
  const [busy, setBusy] = useState(false)

  // The inventory lives in the Device Inventory, which the user can edit from
  // elsewhere (or a scan can grow) — pull a fresh list when adding.
  const refreshInventory = useRackStore((s) => s.refreshInventory)
  useEffect(() => {
    if (!isEdit) void refreshInventory()
  }, [isEdit, refreshInventory])

  // That refetch can drop the preselected entry (racked from elsewhere, deleted),
  // leaving the select blank while the state still held the dead id.
  useEffect(() => {
    if (isEdit) return
    setInventoryId((current) =>
      current && !unracked.some((i) => i.id === current) ? '' : current,
    )
  }, [isEdit, unracked])

  /** Swapping the plate reseeds size and ports — the old ports belong to it. */
  function pickFaceplate(id: string) {
    const plate = getFaceplate(id)
    setFaceplateId(id)
    setUHeight(plate.uHeight)
    setColSpan(plate.colSpan)
    setColStart((c) => Math.min(c, RACK_COLUMNS - plate.colSpan))
    // Coming back to the plate the device already wears is not a change: keep
    // its own ports, ids included. Reseeding them would hand `setPorts` a list
    // of unknown ids on save and take every cable on the device down with it.
    const reverted = device && id === device.faceplateId
    setLocalPorts(
      reverted ? device.ports : plate.ports.map((p) => ({ ...p, id: generateUUID() })),
    )
    setPlateChanged(!reverted)
  }

  /** Accessories and devices draw from disjoint halves of the catalog. */
  function pickSource(next: Source) {
    setSource(next)
    const wantAccessory = next === 'accessory'
    if ((getFaceplate(faceplateId).kind === 'accessory') !== wantAccessory) {
      pickFaceplate(wantAccessory ? 'blank-1u' : 'server-1u')
    }
  }

  function applyInventoryItem(item: InventoryDevice) {
    setInventoryId(item.id)
    if (!label.trim()) setLabel(item.label)
    // Seed the entry's current colour, not `auto`: following the node's check
    // is the user's call, made in the Status select.
    setStatus(item.status)
    pickFaceplate(item.suggestedFaceplateId)
  }

  /**
   * A device picked in the Device Inventory modal.
   *
   * That modal reads `pending_devices` directly, while the rack keeps its own
   * rackable-and-flagged copy — so a row can be visible there and absent here
   * (added since this form opened, or a kind no rack can hold). Refetch once
   * before refusing, and never mount a device twice in the same design.
   */
  async function handlePickFromInventory(picked: PendingDevice) {
    let entry = inventory.find((i) => i.id === picked.id)
    if (!entry) {
      await refreshInventory()
      entry = useRackStore.getState().inventory.find((i) => i.id === picked.id)
    }
    if (!entry) {
      toast.error('That device cannot be mounted in a rack')
      return
    }
    if (entry.racked) {
      toast.error(`${entry.label} is already mounted in this design`)
      return
    }
    applyInventoryItem(entry)
    setInventoryPickerOpen(false)
  }

  /**
   * Repointing needs a mount to repoint: a device being created has none yet,
   * and an accessory stands for no hardware at all.
   */
  const canRelink = isEdit && !!device?.deviceId

  /**
   * Another inventory entry, picked by hand.
   *
   * Applied straight away rather than on Save: the panel, the Status select and
   * the plate LED all read the link from the store, and the picker is an
   * explicit action of its own. It is persisted with the rest of the canvas on
   * the next save, like every other rack edit.
   */
  async function handleRelink(entry: InventoryDevice) {
    setDevicePickerOpen(false)
    if (!device) return
    if (await relinkDevice(device.id, entry.id)) {
      // The plate may have taken the entry's name; keep the open form in step.
      const next = useRackStore.getState().devices.find((d) => d.id === device.id)
      if (next) setLabel(next.label)
      toast.success(`Linked to ${entry.label}`)
    } else {
      toast.error(`${entry.label} is already mounted in this design`)
    }
  }

  /**
   * The Device Inventory row behind this mount: the entry being picked while
   * adding, the one the mount was created from while editing.
   */
  const selectedEntry = inventory.find((i) => i.id === inventoryId)
  const mountEntry = isEdit ? inventory.find((i) => i.id === device?.deviceId) : selectedEntry

  // "Check device" needs a canvas node to read a check from — one the mount
  // already carries, or one the picked entry resolves to.
  const canCheck = (isEdit && !!device?.nodeId) || canFollowNode(mountEntry)

  // Losing that link (another entry picked, node deleted) must not leave the
  // form on a status nothing can resolve.
  useEffect(() => {
    if (!canCheck) setStatus((s) => (s === 'auto' ? 'unknown' : s))
  }, [canCheck])

  const geometry = { uStart, uHeight, colStart, colSpan }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setBusy(true)
    try {
      const id = isEdit ? commitEdit() : await commitCreate()
      if (!id) return
      setPorts(id, ports)
      onClose()
    } finally {
      setBusy(false)
    }
  }

  function commitEdit(): string | null {
    if (!device) return null
    // A plate the rack has no room for changes nothing — and the caller would
    // still write the new plate's ports onto the old faceplate, silently.
    if (plateChanged && faceplateId !== device.faceplateId) {
      if (!applyFaceplate(device.id, faceplateId)) {
        toast.error('No room in the rack for that faceplate')
        return null
      }
    }
    const name = label.trim() || device.label
    if (!updateDevice(device.id, { ...geometry, label: name, status, color, portVisibility })) {
      toast.error('No room in the rack for that size')
      return null
    }
    return device.id
  }

  async function commitCreate(): Promise<string | null> {
    if (!rackId) {
      toast.error('Add a rack first')
      return null
    }
    const name = label.trim()

    if (source === 'accessory') {
      // Hand the mount the whole geometry: it snaps to the nearest slot that
      // fits, and patching it afterwards would drag the plate back off it.
      const id = mountAccessory(faceplateId, rackId, geometry)
      if (!id) return noRoom()
      updateDevice(id, { label: name || getFaceplate(faceplateId).label, color, portVisibility })
      return id
    }

    let entryId = inventoryId
    if (source === 'new') {
      if (!name) {
        toast.error('Name the device first')
        return null
      }
      // `createInventoryDevice` POSTs straight to the Device Inventory, so a
      // mount that fails afterwards would leave a row behind — and a second one
      // on every retry. Check the rack has a slot before creating anything.
      const rack = racks.find((r) => r.id === rackId)
      if (!rack || !findSlot(rack, devices, geometry)) return noRoom()
      // Nothing discovered this device, so the plate is what says what it is —
      // otherwise the inventory row shows up with no type, no icon, no filter.
      const created = await createInventoryDevice({
        label: name,
        type: deviceTypeForFaceplate(faceplateId),
        ip: newIp.trim() || null,
      })
      if (!created) {
        toast.error('Could not add the device to the inventory')
        return null
      }
      entryId = created.id
    }
    if (!entryId) {
      toast.error('Pick a device from the inventory')
      return null
    }
    const id = mountFromInventory(entryId, rackId, { ...geometry, faceplateId })
    if (!id) return noRoom()
    // The mount takes its label and status from the inventory entry, and its
    // slot from `findSlot` — only patch what the form actually overrides.
    updateDevice(id, { status, color, portVisibility, ...(name ? { label: name } : {}) })
    return id
  }

  function noRoom(): null {
    toast.error('No free slot in this rack')
    return null
  }

  function handleUnmount() {
    if (!device) return
    unmountDevice(device.id)
    onClose()
  }

  const showInventoryPicker = !isEdit && source === 'inventory'
  /**
   * Rack furniture — a blank panel, a shelf, a cable manager. It stands for no
   * inventory row, so it carries no ports and gets no port UI at all.
   */
  const isAccessory = isEdit ? !device?.deviceId : source === 'accessory'
  // The plate preview draws a colour, never the word `auto`.
  const previewStatus = resolveDeviceStatus(
    { status, deviceId: mountEntry?.id ?? null },
    inventory,
  )

  return (
    <Dialog open onOpenChange={(o) => !o && onClose()}>
      {/* Wider than NodeModal: the form is two columns, and under them sits the
          faceplate at rack proportions — the plate is where ports are placed, so
          it has to be big enough to aim at. */}
      <DialogContent className="border-[#30363d] bg-[#161b22] text-foreground max-w-[calc(100%-2rem)] sm:max-w-5xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-sm font-semibold">
            {isEdit ? 'Edit Device' : 'Add Device'}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={(e) => void handleSubmit(e)} className="mt-2 flex flex-col gap-3">
          {!isEdit && (
            <Field label="Source">
              <div className="flex gap-1">
                {(
                  [
                    ['inventory', 'From inventory'],
                    ['new', 'New device'],
                    ['accessory', 'Accessory'],
                  ] as [Source, string][]
                ).map(([value, text]) => (
                  <button
                    key={value}
                    type="button"
                    onClick={() => pickSource(value)}
                    className={`flex-1 cursor-pointer rounded border px-2 py-1 text-xs ${
                      source === value
                        ? 'border-[#00d4ff] text-[#00d4ff]'
                        : 'border-[#30363d] text-muted-foreground hover:text-foreground'
                    }`}
                  >
                    {text}
                  </button>
                ))}
              </div>
            </Field>
          )}

          {/* The strip leads with the two things the user checks first: what
              this mount actually stands for, and the plate it wears. The plate
              is drawn at rack proportions — coordinates are unit fractions, so
              the blow-up never reaches the saved data. The two halves are
              spelled out rather than `sm:grid-cols-2` so the strip stays
              distinguishable from the form grid below it. */}
          <div className="grid gap-3 sm:grid-cols-[1fr_1fr]">
            <LinkedDevicePanel
              entry={mountEntry}
              status={previewStatus}
              onLink={canRelink ? () => setDevicePickerOpen(true) : undefined}
            />
            <div className="flex flex-col gap-2">
              {/* The catalog is visual, so the plate name doubles as the button
                  that opens it — the drawing below is the real preview. */}
              <SectionHeader
                aside={
                  <button
                    type="button"
                    aria-label="Faceplate"
                    data-faceplate={faceplateId}
                    onClick={() => setPickerOpen(true)}
                    className="flex max-w-[65%] cursor-pointer items-center gap-1.5 rounded border border-[#30363d] px-2 py-0.5 text-[11px] hover:border-[#00d4ff]"
                  >
                    {/* The current plate names itself; `Change` is what says the
                        name is a button and not a read-out. */}
                    <span className="truncate text-muted-foreground">
                      {getFaceplate(faceplateId).label}
                    </span>
                    <span className="shrink-0 text-[#00d4ff]">Change</span>
                  </button>
                }
              >
                Faceplate
              </SectionHeader>
              <FaceplatePicker
                open={pickerOpen}
                value={faceplateId}
                kind={!isEdit && source === 'accessory' ? 'accessory' : undefined}
                onPick={pickFaceplate}
                onClose={() => setPickerOpen(false)}
              />
              {plateChanged && isEdit && (
                <p className="text-[11px] text-[#e3b341]">
                  Changing the plate replaces its ports and drops their patches.
                </p>
              )}
              <div className="flex flex-1 flex-col items-center justify-center gap-2 rounded border border-[#30363d] bg-[#0d1117] p-3">
                <PortPositionEditor
                  faceplateId={faceplateId}
                  label={label || getFaceplate(faceplateId).label}
                  status={previewStatus}
                  ports={ports}
                  uHeight={uHeight}
                  colSpan={colSpan}
                  color={color}
                  interactive={positioning && !isAccessory}
                  selectedPortId={selectedPortId}
                  onSelect={setSelectedPortId}
                  onChange={setLocalPorts}
                />
              </div>
            </div>
          </div>

          {/* Left column: what the device is and where it sits. Right column:
              its ports, which is the list that used to push everything else
              below the fold. */}
          <div className="grid gap-x-4 gap-y-3 sm:grid-cols-2">
            <div className="flex flex-col gap-3">
            <SectionHeader>Information</SectionHeader>
            {showInventoryPicker && (
              <Field label="Device Inventory entry">
                {/* Opens the real Device Inventory rather than a flat <select>:
                    the user gets its search, source/type filters and the tech
                    detail on each card to tell look-alike hosts apart. */}
                <button
                  type="button"
                  aria-label="Device Inventory entry"
                  data-device-id={inventoryId}
                  onClick={() => setInventoryPickerOpen(true)}
                  className="flex cursor-pointer flex-col items-start gap-0.5 rounded border border-[#30363d] bg-[#21262d] px-2 py-1.5 text-left hover:border-[#00d4ff]"
                >
                  <span className="text-sm">
                    {selectedEntry ? inventoryOption(selectedEntry) : 'No device picked yet'}
                  </span>
                  <span className="text-[11px] text-[#00d4ff]">
                    {selectedEntry ? 'Change device…' : 'Browse the Device Inventory…'}
                  </span>
                </button>
                {unracked.length === 0 && (
                  <p className="text-[11px] text-muted-foreground">
                    Everything in the inventory is already racked — create a new device instead.
                  </p>
                )}
                {/* Rendered inside this DialogContent on purpose: an open Base UI
                    dialog marks outside content inert, so a sibling overlay would
                    be unclickable. */}
                <PendingDevicesModal
                  open={inventoryPickerOpen}
                  onClose={() => setInventoryPickerOpen(false)}
                  onPick={(d) => void handlePickFromInventory(d)}
                  initialRackableOnly
                />
              </Field>
            )}

            {!isEdit && source === 'new' && (
              <Field label="IP (optional)">
                <input
                  className={`${inputClass} font-mono`}
                  aria-label="IP"
                  value={newIp}
                  onChange={(e) => setNewIp(e.target.value)}
                  placeholder="192.168.1.10"
                />
              </Field>
            )}

            {!isEdit && racks.length > 1 && (
              <Field label="Rack">
                <select
                  className={inputClass}
                  aria-label="Rack"
                  value={rackId}
                  onChange={(e) => setRackId(e.target.value)}
                >
                  {racks.map((r) => (
                    <option key={r.id} value={r.id}>
                      {r.name}
                    </option>
                  ))}
                </select>
              </Field>
            )}

            <Field label="Label">
              <input
                className={inputClass}
                aria-label="Label"
                value={label}
                onChange={(e) => setLabel(e.target.value)}
                placeholder={source === 'accessory' ? getFaceplate(faceplateId).label : 'Device name'}
              />
            </Field>

            <SectionHeader>Placement</SectionHeader>

            <div className="grid grid-cols-2 gap-3">
              <Field label="U position">
                <input
                  type="number"
                  min={1}
                  className={inputClass}
                  aria-label="U position"
                  value={uStart}
                  onChange={(e) => setUStart(Number(e.target.value) || 1)}
                />
              </Field>
              <Field label="Height (U)">
                <input
                  type="number"
                  min={1}
                  max={12}
                  className={inputClass}
                  aria-label="Height (U)"
                  value={uHeight}
                  onChange={(e) => setUHeight(Number(e.target.value) || 1)}
                />
              </Field>
              <Field label="Column">
                <input
                  type="number"
                  min={0}
                  max={RACK_COLUMNS - 1}
                  className={inputClass}
                  aria-label="Column"
                  value={colStart}
                  onChange={(e) => setColStart(Number(e.target.value) || 0)}
                />
              </Field>
              <Field label={`Width (/${RACK_COLUMNS})`}>
                <select
                  className={inputClass}
                  aria-label="Width"
                  value={colSpan}
                  onChange={(e) => setColSpan(Number(e.target.value))}
                >
                  <option value={RACK_COLUMNS}>Full width</option>
                  <option value={RACK_COLUMNS / 2}>Half width</option>
                  <option value={RACK_COLUMNS / 3}>Third width</option>
                  <option value={RACK_COLUMNS / 4}>Quarter width</option>
                  <option value={RACK_COLUMNS / 6}>Sixth width</option>
                </select>
              </Field>
            </div>

            <div className="grid grid-cols-2 gap-3">
            <Field label="Status">
              <select
                className={inputClass}
                aria-label="Status"
                value={status}
                onChange={(e) => setStatus(e.target.value as MountStatus)}
              >
                {/* Only offered when there is a node to read: the rack runs no
                    check of its own. */}
                {canCheck && <option value="auto">Check device (live)</option>}
                <option value="online">Online</option>
                <option value="offline">Offline</option>
                <option value="unknown">Unknown</option>
              </select>
              {status === 'auto' && (
                <p className="text-[11px] text-muted-foreground">
                  Follows the status check configured on the matching canvas node.
                </p>
              )}
            </Field>

            <Field label="Colour override">
              <div className="flex items-center gap-2">
                <input
                  type="color"
                  aria-label="Colour override"
                  className="h-8 flex-1 cursor-pointer rounded border border-[#30363d] bg-[#21262d]"
                  value={color ?? DEFAULT_COLOR}
                  onChange={(e) => setColor(e.target.value)}
                />
                <button
                  type="button"
                  onClick={() => setColor(undefined)}
                  className="rounded border border-[#30363d] px-2 py-1 text-[11px] text-muted-foreground hover:text-foreground cursor-pointer"
                >
                  Reset
                </button>
              </div>
            </Field>
            </div>
            </div>

            <div className="flex flex-col gap-3">
            {/* An accessory has no ports, so it gets no heading either — a
                rule over an empty column reads as a missing section. */}
            {!isAccessory && (
              <>
                <SectionHeader>Ports</SectionHeader>
                <PortListEditor
                  ports={ports}
                  onChange={setLocalPorts}
                  positioning={positioning}
                  onPositioningChange={setPositioning}
                  selectedPortId={selectedPortId}
                  onSelect={setSelectedPortId}
                />

                {/* How the canvas draws these sockets — a display choice about
                    this mount, not a fact about the hardware, so it stays on
                    the mount and never reaches the inventory entry. */}
                <Field label="Show ports on the canvas">
                  <select
                    className="h-8 w-full rounded border border-[#30363d] bg-[#21262d] px-2 text-xs cursor-pointer"
                    aria-label="Show ports on the canvas"
                    value={portVisibility}
                    onChange={(e) => setPortVisibility(e.target.value as PortVisibility)}
                  >
                    <option value="auto">Automatic (switches and patch panels)</option>
                    <option value="always">Always</option>
                    <option value="hover">On hover or selection</option>
                  </select>
                </Field>
              </>
            )}

            {canRelink && devicePickerOpen && (
              /* Inside this DialogContent for the same reason as the inventory
                 picker: an open Base UI dialog makes outside content inert.
                 Mounted per opening, so the inventory is fetched fresh. */
              <DevicePickerModal
                open={devicePickerOpen}
                value={device?.deviceId}
                onPick={handleRelink}
                onClose={() => setDevicePickerOpen(false)}
              />
            )}
            </div>
          </div>

          {/* Rule between the form and its actions, so Save never reads as part
              of the last section. */}
          <div className="mt-1 flex items-center gap-2 border-t border-[#30363d] pt-3">
            {isEdit && (
              <Button
                type="button"
                variant="ghost"
                onClick={handleUnmount}
                className="cursor-pointer text-[#f85149] hover:bg-[#f8514922] hover:text-[#f85149]"
              >
                Unmount{device?.deviceId ? ' (stays in inventory)' : ''}
              </Button>
            )}
            <div className="ml-auto flex gap-2">
              <Button type="button" variant="ghost" onClick={onClose} className="cursor-pointer">
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={busy}
                className="cursor-pointer bg-[#00d4ff] text-[#0d1117] hover:bg-[#00b8e0]"
              >
                {isEdit ? 'Save' : 'Add'}
              </Button>
            </div>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  )
}
